insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-c0d8b2d30585', 'en', 'B2', 'Advanced Reported Speech', 'No nível B2, você já sabe relatar falas simples com ''said'' e ''told''. Agora, vamos aprofundar: como expressar perguntas, pedidos, conselhos e como lidar com mudanças de tempo, pronomes e expressões de tempo e lugar. Este tópico ajuda você a soar mais natural e a transmitir informações com precisão, tanto em conversas informais quanto em contextos formais, como reuniões de trabalho ou discussões acadêmicas.', 'Para formar o discurso indireto (reported speech), usamos um verbo introdutório (say, tell, ask, etc.) e ajustamos a frase original. Regras principais: 1) Recuo dos tempos verbais (por exemplo, presente vira passado, passado vira passado perfeito). 2) Mudança de pronomes e possessivos. 3) Ajuste de expressões de tempo e lugar (agora vira então, aqui vira ali, etc.). 4) Em perguntas, invertemos a ordem para a forma afirmativa e usamos se ou se (if/whether) para perguntas sim/não. 5) Pedidos e ordens usam ''ask'' ou ''tell'' + pessoa + infinitivo.', '["Relatar o que alguém disse em uma conversa, mantendo o sentido original.","Transmitir perguntas feitas por outras pessoas sem usar aspas.","Reportar pedidos, conselhos, sugestões e ordens.","Descrever o que alguém pensou ou acreditou, usando ''thought'' ou ''believed''.","Compartilhar notícias ou informações de fontes como jornais ou colegas.","Em situações formais, como em reuniões ou apresentações, para citar declarações."]'::jsonb, '["Usar ''say'' e ''tell'' de forma intercambiável: ''He said me'' é incorreto; ''tell'' exige objeto.","Esquecer de recuar os tempos verbais: ''She says she is tired'' vira ''She said she was tired''.","Manter a ordem de pergunta no discurso indireto: ''He asked where was I'' deve ser ''He asked where I was''.","Não ajustar expressões de tempo/lugar: ''today'' deve virar ''that day''.","Confundir ''if'' e ''whether'' em perguntas sim/não: ambos são corretos, mas ''whether'' é mais formal.","Usar ''that'' após ''ask'' em perguntas indiretas: ''She asked that if I was coming'' é incorreto; deve ser ''She asked if I was coming''."]'::jsonb, '["Se o verbo introdutor estiver no presente (ex.: ''She says''), o tempo da frase original não muda.","Se a frase relatada for uma verdade universal ou fato, o tempo pode permanecer o mesmo: ''He said the Earth is round''.","Os verbos modais ''would'', ''should'', ''could'', ''might'', ''must'' geralmente não mudam no discurso indireto.","Em pedidos e ordens, use ''ask'' ou ''tell'' + pessoa + infinitivo, sem ''that''.","Em perguntas indiretas, a ordem é sujeito + verbo, sem o auxiliar ''do/does/did''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

