insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-8c91bef080d4', 'en', 'B2', 'Inversion and Emphasis: Making Your English More Expressive', 'Nesta lição, você vai aprender a usar a inversão para dar ênfase em inglês. A inversão é uma técnica que coloca o verbo antes do sujeito, criando um efeito dramático ou formal. Você vai ver como usá-la com expressões negativas, ''so'', ''such'', e em frases condicionais. Isso vai tornar seu inglês mais sofisticado e natural.', 'Para formar a inversão, você coloca o verbo auxiliar (ou o verbo ''to be'') antes do sujeito, e o verbo principal depois do sujeito. Isso acontece principalmente quando a frase começa com uma expressão negativa ou restritiva, como ''never'', ''rarely'', ''not only'', ''hardly'', ''no sooner'', ''little'', etc. Exemplos: ''Never have I seen such a beautiful sunset.'' (Nunca vi um pôr do sol tão bonito.) e ''Not only did she finish the project, but she also presented it.'' (Ela não só terminou o projeto, mas também o apresentou.)', '["Para dar ênfase a uma ação ou estado, especialmente com advérbios negativos ou restritivos no início da frase.","Para criar um tom formal ou literário em textos escritos ou discursos.","Com ''so'' e ''such'' para expressar consequência ou resultado: ''So tired was she that she fell asleep.''","Em condicionais sem ''if'' quando a condição é irreal ou pouco provável: ''Had I known, I would have acted differently.''","Após expressões como ''in no way'', ''under no circumstances'', ''at no time'' para enfatizar uma proibição ou negação."]'::jsonb, '["Usar inversão com advérbios de frequência comuns, como ''often'' ou ''always'' – inversão é opcional com ''often'', mas não com ''always''.","Esquecer de usar o verbo auxiliar ''do'' para formar a inversão em frases no presente ou passado simples.","Inverter em perguntas simples de forma incorreta: ''What are you doing?'' (não inverta com auxiliar extra).","Colocar o verbo principal antes do sujeito sem usar o auxiliar, ex.: ''Never I have seen''.","Usar inversão em frases que começam com ''not'' como negação simples, sem a estrutura correta."]'::jsonb, '["A inversão é mais comum na linguagem formal e escrita do que na fala cotidiana.","Em inglês falado, muitas vezes usamos a ordem normal e adicionamos ênfase com a entonação.","Preste atenção aos tempos verbais: com ''never'' + present perfect, use o auxiliar ''have'' antes do sujeito.","Pratique com exemplos para internalizar a estrutura.","Não confunda inversão com perguntas – em perguntas, a inversão é obrigatória, mas aqui é uma escolha estilística."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

