insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-2dbec5766d6a', 'en', 'B2', 'Perfect and Perfect Continuous Tenses', 'Neste tópico, você vai aprender a usar os tempos perfect (present perfect, past perfect) e perfect continuous (present perfect continuous, past perfect continuous) para expressar ações concluídas ou em andamento com relevância para outro momento. Vamos focar na diferença entre simples e contínuo, e como escolher o tempo certo em situações complexas.', 'Present Perfect: have/has + past participle (ex: have done). Past Perfect: had + past participle (ex: had done). Present Perfect Continuous: have/has been + present participle (ex: have been doing). Past Perfect Continuous: had been + present participle (ex: had been doing).', '["Present Perfect: para experiências de vida, ações passadas com resultado no presente, e com ever/never/just/already/yet.","Present Perfect Continuous: para ações que começaram no passado e continuam até agora, enfatizando a duração ou que estão em andamento.","Past Perfect: para ações concluídas antes de outra ação no passado.","Past Perfect Continuous: para ações que estavam em andamento antes de um momento no passado, enfatizando a duração."]'::jsonb, '["Usar present perfect em vez de past simple com tempo definido (ex: I have seen her yesterday - errado).","Confundir present perfect continuous com present perfect simple quando o resultado é mais importante que a duração.","Usar past perfect em vez de past simple quando a ordem das ações é clara pelo contexto.","Esquecer de usar ''been'' na forma contínua do perfect (ex: I have working - errado)."]'::jsonb, '["Use ''for'' com duração e ''since'' com ponto de partida.","Os tempos perfect continuous não costumam ser usados com stative verbs (like, believe, know).","Na fala, contrações são comuns: I''ve, he''s, we''d, etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

