insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-aac74cc860df', 'en', 'B2', 'Mastering the Past Perfect for Clear Narratives', 'Neste tópico, você vai dominar o uso do Past Perfect para organizar narrativas no passado, deixando claro qual evento aconteceu primeiro. Você aprenderá a formar esse tempo verbal, quando usá-lo e como evitar erros comuns. As atividades vão ajudá-lo a aplicar esse conhecimento em contextos práticos do dia a dia.', 'O Past Perfect é formado com o passado do verbo ''to have'' (had) + o particípio passado do verbo principal. Para verbos regulares, o particípio passado é formado adicionando ''-ed'' (ex: worked, played). Verbos irregulares têm formas próprias (ex: gone, seen, eaten). Exemplos: ''I had finished'', ''She had not seen'', ''Had they arrived?''.', '["Para indicar uma ação que aconteceu antes de outra ação no passado: ''When I arrived, the meeting had already started.''","Para falar de experiências ou fatos que ocorreram antes de um momento específico no passado: ''By 2005, she had lived in three different countries.''","No discurso indireto para reportar algo que alguém tinha dito: ''He said that he had never been to Brazil.''","Em frases com ''wish'' para expressar arrependimento sobre o passado: ''I wish I had studied harder.''"]'::jsonb, '["Usar o Past Perfect quando o Simple Past é suficiente, como em ações sequenciais: ''I woke up, had breakfast, and left'' (não ''had woken'').","Confundir com o Present Perfect: lembre-se de que o Past Perfect é usado para um passado anterior a outro passado, não até o presente.","Esquecer de usar ''had'' com verbos irregulares, como ''I seen'' em vez de ''I had seen''."]'::jsonb, '["Use ''hadn''t'' como forma negativa contraída.","Em perguntas, inverta o sujeito e o ''had'': ''Had you finished before the deadline?''","O Past Perfect é comum em narrativas para dar contexto de eventos anteriores."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

