insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-11217a0fa978', 'en', 'B2', 'Past Modals: Degrees of Certainty and Regret', 'Os past modals (modal + have + past participle) são usados para fazer suposições, críticas ou expressar arrependimento sobre ações passadas. Nesta lição, você aprenderá a usar must have, might have, could have, should have e would have para falar sobre o passado com diferentes níveis de certeza e emoção.', 'Estrutura: [modal] + have + [past participle]. Exemplos: must have done, might have gone, could have seen, should have studied, would have arrived.', '["Deduções lógicas sobre o passado: ''The ground is wet. It must have rained.''","Possibilidades no passado: ''She might have missed the bus.''","Habilidade não realizada: ''He could have won the race, but he fell.''","Crítica ou conselho não seguido: ''You should have told me earlier.''","Condições irreais no passado: ''If I had known, I would have gone.''"]'::jsonb, '["Usar ''must have'' para possibilidades (deve ser ''might have'').","Usar ''should have'' para deduções (deve ser ''must have'').","Usar ''could have'' para obrigações (deve ser ''should have'').","Esquecer o ''have'' (ex: ''I must seen it'' em vez de ''I must have seen it'').","Usar ''would have'' sem uma condição implícita ou explícita."]'::jsonb, '["Observe que ''must have'' expressa certeza lógica, enquanto ''might have'' expressa incerteza.","''Could have'' também pode ser usado para criticar alguém por não fazer algo: ''You could have helped me.''","Na fala, ''have'' é frequentemente reduzido: ''must''ve'', ''could''ve'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

