insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-1da46040585f', 'en', 'B2', 'Inversion and Emphasis: Introduction', 'Nesta lição, você vai aprender a usar a inversão para dar ênfase em frases em inglês. A inversão é uma técnica que coloca o verbo antes do sujeito, geralmente em contextos formais ou literários, para destacar uma ideia ou criar um efeito dramático. Vamos explorar as estruturas mais comuns, como ''Never have I seen...'', ''Not only... but also...'', e ''Little did I know...''.', 'A inversão ocorre quando o verbo auxiliar (ou modal) é colocado antes do sujeito, e o verbo principal permanece depois. Isso acontece frequentemente após certos advérbios negativos ou restritivos no início da frase, como ''never'', ''rarely'', ''seldom'', ''not only'', ''little'', ''hardly'', ''no sooner'', ''only after'', ''only when'', entre outros. Exemplo: ''Never have I seen such a beautiful sunset.'' (Nunca vi um pôr do sol tão bonito.)', '["Para enfatizar uma experiência negativa ou rara: ''Rarely do we witness such honesty.''","Para expressar surpresa ou ironia: ''Little did I know that she was my cousin.''","Para dar ênfase a uma ação que acontece em sequência: ''No sooner had I arrived than the phone rang.''","Para enfatizar uma condição: ''Only if you work hard can you succeed.''","Para estruturas com ''Not only... but also...'': ''Not only is she intelligent, but she is also very kind.''"]'::jsonb, '["Esquecer de usar o auxiliar na inversão: ''Never I have seen...'' (correto: ''Never have I seen...'')","Usar inversão com advérbios afirmativos: ''Always he is late.'' (deve ser: ''He is always late.'')","Inverter em perguntas indiretas: ''I wonder where is he.'' (deve ser: ''I wonder where he is.'')","Usar inversão após ''only'' quando não há ênfase: ''Only he knows the answer.'' (não inverte porque ''only'' modifica o sujeito)"]'::jsonb, '["A inversão é mais comum em inglês formal, escrito, literário e em discursos.","Após ''not only'' no início, a oração principal também é invertida, como em: ''Not only is he a good teacher, but he is also a great mentor.''","Com ''no sooner'' e ''hardly'', use o passado perfeito: ''No sooner had I left than it started to rain.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

