insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-ad5c8ceed9d3', 'en', 'B2', 'Participle Clauses', 'As participle clauses são orações reduzidas que usam o particípio presente (-ing) ou o particípio passado (-ed / terceira coluna) para expressar tempo, causa, condição, ou para dar informações adicionais sobre o sujeito. Elas tornam o discurso mais conciso e sofisticado, comuns em textos formais e na fala cotidiana de falantes nativos.', 'Para formar uma participle clause, você remove o sujeito e o verbo auxiliar da oração subordinada, mantendo o verbo principal no particípio. Se a oração for ativa, use o particípio presente (ex.: ''Walking home, I saw a friend.''). Se for passiva, use o particípio passado (ex.: ''Given the opportunity, she would succeed.''). A participle clause pode aparecer no início, meio ou fim da frase, e deve concordar com o sujeito da oração principal.', '["Para expressar duas ações simultâneas: ''She sat by the window, reading a book.''","Para expressar uma ação que ocorre antes de outra: ''Having finished the report, he went out for lunch.''","Para expressar causa: ''Being tired, I went to bed early.''","Para expressar condição: ''Given more time, we could have done better.''","Para acrescentar informação sem repetir o sujeito: ''The man, wearing a blue suit, is my boss.''"]'::jsonb, '["Usar a participle clause com sujeito diferente da oração principal (participle dangling).","Confundir o particípio presente com o gerúndio em contextos de sujeito.","Esquecer de usar o particípio passado em orações passivas.","Colocar a participle clause após uma pausa inadequada, alterando o sentido."]'::jsonb, '["Participle clauses são mais comuns na escrita formal e acadêmica.","Em inglês falado, é mais frequente usar orações completas com ''because'', ''when'', etc.","O particípio presente também é usado em frases como ''Feeling hungry, she opened the fridge.''","Cuidado com o particípio passado de verbos irregulares (ex.: ''written'', ''broken'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

