insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-18a718a6fdc7', 'en', 'B2', 'Past Perfect for Narrative Control', 'O Past Perfect (had + particípio passado) é usado para indicar uma ação que ocorreu antes de outra ação no passado. Ele permite organizar eventos em uma narrativa, deixando claro qual aconteceu primeiro. Neste tópico, você vai aprender a formar e usar o Past Perfect para contar histórias de forma mais precisa, especialmente para descrever causas e contextos anteriores.', 'Formação: Sujeito + had + past participle (para todas as pessoas). Forma negativa: had not (hadn''t) + past participle. Interrogativa: Had + sujeito + past participle? Exemplos: ''I had finished'' (Eu tinha terminado), ''She hadn''t seen'' (Ela não tinha visto), ''Had they left?'' (Eles tinham saído?). O particípio passado de verbos regulares termina em -ed (e.g., finished, played); verbos irregulares têm formas próprias (e.g., gone, seen, written).', '["Para descrever uma ação que aconteceu antes de outra ação no passado: ''When I arrived, the meeting had already started.''","Para explicar a causa de um estado no passado: ''She was tired because she had worked all night.''","Para narrar eventos em ordem não cronológica, criando um flashback: ''He remembered the day he had met her.''","Para expressar desejos ou condições irreais no passado (com ''wish'' ou ''if only''): ''I wish I had studied more.''"]'::jsonb, '["Usar o Past Simple em vez do Past Perfect quando a ordem dos eventos precisa ser clara: ''After I ate, I went out'' (ambos no passado, mas ''after'' já indica ordem; no entanto, sem ''after'', usa-se Past Perfect: ''I had eaten before I went out'').","Confundir a forma do particípio passado de verbos irregulares: ''I had went'' (errado) → ''I had gone'' (correto).","Esquecer de usar ''had'' na negativa: ''I hadn''t seen'' (não ''I didn''t had seen'').","Usar o Past Perfect quando não há necessidade de mostrar anterioridade, sobrecarregando a frase."]'::jsonb, '["O Past Perfect é frequentemente usado com ''before'', ''after'', ''by the time'', ''when'', ''already'', ''just'', ''yet'', ''never''.","Em narrativas, o Past Perfect é usado para dar contexto inicial, enquanto o Past Simple narra os eventos principais.","A contração ''hadn''t'' é comum na fala, mas na escrita formal evite contrações.","Atenção: ''had had'' é possível: ''She had had a great time before the accident.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

