insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b2-dfc441a8b758-exercise-05', 'en', 'B2', 'Complete the mixed conditional', 'Para falar de uma ação passada que afeta o presente, use: If + past perfect, would + base form.', 'If I had saved more money, I would be able to travel now.', 'If they ___ the house last year, they ___ in debt now.', '["bought / wouldn''t be","had bought / wouldn''t be","would buy / weren''t","buy / aren''t"]'::jsonb, 1, 5, true, 'generated-grammar-en-b2-dfc441a8b758')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-9f987da26df1', 'en', 'B2', 'Past Modals: Expressing Certainty, Possibility, and Regret', 'Neste tópico, você vai aprender a usar os modais no passado (modal + have + past participle) para expressar diferentes níveis de certeza sobre fatos passados, além de falar sobre arrependimentos e conselhos não seguidos. Vamos explorar as formas afirmativa, negativa e interrogativa, com ênfase no uso em situações cotidianas e profissionais.', 'A estrutura básica é: modal + have + passado do verbo principal (past participle). Exemplos: must have, may have, might have, could have, should have, would have. A forma negativa usa not logo após o modal: must not have, may not have, etc. Considere que ''have'' é sempre invariável, e o past participle é a terceira forma do verbo.', '["Para expressar certeza sobre algo no passado (must have)","Para expressar possibilidade ou incerteza (may have, might have, could have)","Para falar sobre ações possíveis no passado que não aconteceram (could have)","Para dar opinião sobre o que era certo fazer (should have / shouldn''t have)","Para expressar desejo ou condição hipotética (would have)","Para falar sobre ausência de certeza negativa (may not have, might not have)","Para expressar quase-certeza negativa (couldn''t have)"]'::jsonb, '["Usar ''must to have'' em vez de ''must have''","Esquecer de usar o past participle após ''have''","Usar ''should to go'' em vez de ''should have gone''","Confundir o uso de ''must have'' e ''should have'' (certeza vs. opinião)","Usar ''can have'' em vez de ''could have'' para possibilidade passada","Não usar a forma negativa corretamente: ''may not have'' vs. ''may have not''"]'::jsonb, '["Lembre-se de que ''must have'' indica conclusão lógica, enquanto ''should have'' indica um julgamento sobre o que era apropriado.","Em inglês britânico, ''mustn''t have'' pode ser usado para dedução negativa, mas em americano é mais comum ''couldn''t have''.","A contração ''should''ve'' é comum na fala e na escrita informal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

