insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-043a48321fc2', 'en', 'B2', 'Inversion and Emphasis: Introduction', 'A inversão é uma técnica que coloca o verbo auxiliar antes do sujeito, como em perguntas, mas usada em frases afirmativas para dar ênfase ou criar um efeito dramático. Nesta introdução, você aprenderá a usar a inversão com advérbios negativos e expressões como ''not only'', ''rarely'', ''never'', etc., para enfatizar uma ideia e tornar sua fala e escrita mais sofisticadas.', 'Para formar a inversão, coloque o advérbio ou expressão negativa no início da frase, seguido do verbo auxiliar (do, does, did, have, etc.) e depois o sujeito e o verbo principal. Exemplo: ''Never have I seen such a beautiful sunset.'' (Never + have + I + seen). Se o verbo for ''to be'', inverta diretamente: ''Rarely is he late.'' Se não houver auxiliar, use ''do/does/did'' para formar a inversão no presente e passado simples: ''Not only does she sing, but she also dances.''', '["Para enfatizar uma ideia negativa ou surpreendente, como em ''Never have I felt so alive.''","Para dar ênfase em contextos formais ou literários, como em ''Not only did he apologize, but he also offered to help.''","Para criar um efeito dramático em narrativas, como em ''Rarely had she seen such chaos.''","Para enfatizar uma frequência ou condição, como em ''Only after the exam did he realize his mistake.''"]'::jsonb, '["Usar inversão sem um advérbio negativo ou expressão restritiva no início.","Esquecer de usar o auxiliar ''do/does/did'' quando não há outro auxiliar no presente ou passado simples.","Inverter em frases que já têm um auxiliar, mas colocando o sujeito antes do verbo.","Usar inversão em perguntas indiretas, onde a ordem normal é mantida."]'::jsonb, '["A inversão é mais comum em inglês formal e escrito do que na fala cotidiana.","Use a inversão para causar impacto ou dar ênfase, mas evite exagerar.","Lembre-se de que, após expressões como ''not only'', a segunda parte da frase é frequentemente introduzida por ''but also''.","Em frases com ''so'' + adjetivo, a inversão também pode ocorrer, mas isso será tratado em níveis avançados."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

