insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-07bee87b6d79', 'en', 'B2', 'Advanced Passive Structures', 'Neste tópico, você vai explorar estruturas passivas avançadas em inglês, incluindo a passiva com gerúndio, infinitivo, verbos modais e a passiva impessoal. Vamos focar em como usá-las em contextos formais e acadêmicos, com exemplos práticos e exercícios para consolidar seu aprendizado.', 'A voz passiva é formada com o verbo ''to be'' (no tempo correto) + o particípio passado do verbo principal. Nas formas avançadas, temos:

1. Passiva com gerúndio: being + particípio passado (ex: ''being done'').
2. Passiva com infinitivo: to be + particípio passado (ex: ''to be done'').
3. Passiva com modais: modal + be + particípio passado (ex: ''must be done'').
4. Passiva impessoal: it + passiva do verbo de relato (ex: ''it is said that...'').
5. Passiva com objeto + infinitivo: sujeito + passiva do verbo de percepção/causação + to + infinitivo (ex: ''He is believed to be...'').', '["Para dar ênfase à ação em vez do agente, especialmente em textos formais ou científicos.","Para falar de processos e procedimentos, como em manuais ou instruções.","Para relatar opiniões, crenças ou notícias de forma impessoal (ex: ''It is believed that...'').","Para descrever situações em que o agente é desconhecido, óbvio ou irrelevante.","Para evitar responsabilidade ou tornar a afirmação mais diplomática (ex: ''A mistake was made'')."]'::jsonb, '["Usar a passiva com o tempo verbal errado, especialmente em relação à ação (presente, passado, futuro).","Esquecer de usar o particípio passado após ''being'', ''been'' ou ''to be''.","Confundir a passiva com gerúndio e infinitivo em estruturas como ''I remember being told'' vs. ''I want to be told''.","Omitir o ''by'' quando é importante identificar o agente (embora muitas vezes seja omitido).","Usar a passiva impessoal com verbos que não são de relato (ex: ''It is rained'') – o correto é ''It is said'', ''It is believed'', etc."]'::jsonb, '["Na passiva com modais, o modal permanece no mesmo tempo, e ''be'' é invariável (ex: ''should be done'', ''might have been done'').","A passiva impessoal é comum em notícias e textos acadêmicos: ''It is reported that...'', ''It is thought that...''.","Com verbos de percepção e causação (ex: ''believe'', ''know'', ''make''), podemos usar a estrutura: sujeito + passiva + infinitivo (ex: ''He is said to be rich'').","A passiva com gerúndio é usada após preposições e certos verbos (ex: ''I''m tired of being told what to do'').","A passiva com infinitivo é comum após verbos como ''want'', ''need'', ''hope'' (ex: ''The report needs to be finished'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

