insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-1661373750fe', 'en', 'B2', 'Inversion and Emphasis', 'Nesta lição, você vai aprender a usar a inversão para dar ênfase em inglês. A inversão é uma técnica estilística que coloca o verbo auxiliar antes do sujeito, criando um efeito dramático ou formal. Vamos explorar quando e como usá-la, além de evitar erros comuns.', 'A inversão ocorre principalmente com advérbios negativos ou restritivos no início da frase, seguidos pela estrutura auxiliar + sujeito + verbo principal. Por exemplo: ''Never have I seen such a beautiful sunset.'' Outros gatilhos incluem ''rarely'', ''seldom'', ''not only'', ''hardly'', ''no sooner'', ''little''.', '["Para enfatizar uma ação ou estado incomum: ''Rarely do we find such dedication.''","Com expressões de tempo negativo: ''No sooner had we left than it started raining.''","Com ''not only'' para adicionar informação: ''Not only did she pass the exam, but she also got the highest score.''","Em frases formais ou literárias para efeito dramático: ''Little did he know what awaited him.''"]'::jsonb, '["Usar inversão com advérbios comuns como ''often'' ou ''usually'' (incorreto: ''Often do I go there''), quando a inversão é opcional e mais formal.","Esquecer de inverter após ''so'' + adjetivo: ''So tired was I that I fell asleep.'' (correto)","Aplicar inversão em perguntas indiretas: ''I wonder where is the station.'' (incorreto, deve ser ''where the station is'')","Usar inversão em frases sem auxiliar: ''Never I have seen...'' (incorreto, deve ser ''Never have I seen...'')"]'::jsonb, '["A inversão é mais comum em inglês escrito formal e em discursos.","Em conversas informais, geralmente evitamos a inversão.","A inversão também ocorre com ''here'' e ''there'' quando o sujeito é um substantivo: ''Here comes the bus.''"]'::jsonb, 0, true)
