insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-771540cc7e11', 'en', 'B2', 'Participle Clauses: Adding Variety and Precision', 'As orações de particípio (participle clauses) são uma forma de encurtar orações relativas ou adverbiais, tornando seu inglês mais natural e sofisticado. Elas usam o particípio presente (-ing) ou passado (-ed/forma irregular) para expressar ações simultâneas, causas, condições ou resultados. Nesta lição, você vai aprender quando e como usá-las, e como evitar erros comuns.', 'Para formar uma oração de particípio, você geralmente remove o sujeito e o verbo auxiliar de uma oração subordinada, mantendo o verbo principal no particípio. Use o particípio presente (verb + -ing) para ações ativas ou simultâneas, e o particípio passado (verb + -ed ou forma irregular) para ações passivas ou concluídas. Exemplos: ''Because she was tired, she went to bed'' → ''Being tired, she went to bed''; ''The book, which was written in 1990, became a bestseller'' → ''The book, written in 1990, became a bestseller''.', '["Para expressar causa: ''Feeling hungry, I made a sandwich.''","Para expressar tempo: ''Having finished his work, he left the office.''","Para dar informações extras sobre um substantivo (como uma oração relativa reduzida): ''The girl sitting by the window is my sister.''","Para expressar condição: ''Given more time, we could have done better.''","Para expressar resultado: ''The company expanded rapidly, becoming a global leader.''"]'::jsonb, '["Usar particípio presente com sujeito passivo: ''Walking home, the rain started'' (errado) – o sujeito implícito deve ser o mesmo da oração principal. Correto: ''Walking home, I noticed the rain starting.''","Usar particípio passado em vez de presente para ações ativas: ''Felt tired, I went to bed'' (errado) – use ''Feeling tired, I went to bed.''","Esquecer de usar ''having + past participle'' para ações concluídas antes da principal: ''Finishing my homework, I went out'' (errado) – ''Having finished my homework, I went out.''","Criar orações com particípio sem sujeito claro: ''Driving to work, the traffic was heavy'' (errado) – parece que o trânsito estava dirigindo. Correto: ''Driving to work, I encountered heavy traffic.''"]'::jsonb, '["As orações de particípio são mais comuns na escrita formal e acadêmica, mas também aparecem na fala.","Na linguagem informal, muitas vezes usa-se uma oração com ''because'', ''when'', ''if'', etc.","Cuidado com o particípio presente após ''while'' e ''before'': ''While walking, she saw a friend.''","O particípio passado pode ser usado com ''with'' ou ''without'' para indicar acompanhamento: ''He left without saying goodbye.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

