insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-48f77e825138', 'en', 'B2', 'Present Perfect and Present Perfect Continuous: Connecting Past and Present', 'Neste tópico, você vai aprender a usar o Present Perfect e o Present Perfect Continuous em inglês.  O Present Perfect conecta ações passadas ao presente, enquanto o Present Perfect Continuous enfatiza a duração ou continuidade de uma ação.  Você vai entender como formá-los, quando usá-los e como evitar erros comuns.', 'Present Perfect: Sujeito + have/has + particípio passado (verb + -ed ou forma irregular). Exemplo: I have lived here for five years.  Present Perfect Continuous: Sujeito + have/has + been + verbo + -ing. Exemplo: She has been studying all morning.', '["Present Perfect para experiências de vida: ''I have visited Italy twice.''","Present Perfect para ações passadas com resultados no presente: ''She has lost her keys, so she can''t open the door.''","Present Perfect Continuous para ações que começaram no passado e continuam no presente: ''I have been working here since 2010.''","Present Perfect Continuous para ações temporárias ou recentes com evidências: ''You look tired. Have you been running?''","Com palavras como ''already'', ''yet'', ''just'', ''ever'', ''never'' para Present Perfect.","Com ''for'' e ''since'' para ambos os tempos, mas com nuances: Present Perfect para situações permanentes, Present Perfect Continuous para temporárias."]'::jsonb, '["Usar Present Perfect com tempos específicos: ''I have seen him yesterday'' (errado) vs ''I saw him yesterday'' (correto).","Confundir ''since'' e ''for'': ''since'' + ponto no tempo, ''for'' + período.","Esquecer o ''have/has'' na forma negativa: ''I not have done'' (errado) vs ''I haven''t done''.","Usar Present Perfect em vez de Simple Past quando a ação é só passado: ''I have lived there in 2010'' (errado) vs ''I lived there in 2010''.","Usar Present Perfect Continuous com verbos estativos: ''I have been knowing him'' (errado) vs ''I have known him''."]'::jsonb, '["Verbos estativos (like, know, believe) geralmente não usam Present Perfect Continuous.","Com ''for'' e ''since'', a diferença entre os tempos pode ser sutil: Present Perfect Continuous enfatiza a duração da ação.","O Present Perfect Continuous é frequentemente usado com ''all day'', ''all morning'', etc.","Em perguntas, use ''Have you ever...?'' para experiências, ''How long have you...?'' para duração.","A contração ''I''ve'' e ''she''s'' é comum na fala."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

