insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-f2c1a9b1bbdc', 'en', 'B2', 'Past Perfect for Narrative Control', 'O Past Perfect é usado para expressar uma ação que ocorreu antes de outra ação no passado. Ele permite organizar eventos de forma clara e lógica, mostrando qual acontecimento teve prioridade. Nesta lição, você aprenderá a formar e usar o Past Perfect corretamente, com foco em narrativas e relatos de experiências.', 'O Past Perfect é formado com o auxiliar ''had'' (para todas as pessoas) + o particípio passado do verbo principal (verbos regulares terminam em -ed; verbos irregulares têm formas próprias, como ''gone'', ''seen'', ''written''). Estruturas: Afirmativa: Sujeito + had + particípio passado. Negativa: Sujeito + had not (hadn''t) + particípio passado. Interrogativa: Had + sujeito + particípio passado?', '["Para indicar uma ação que aconteceu antes de outra ação no passado (ex.: ''When I arrived, she had already left.'').","Em narrativas para dar contexto ou explicar a causa de eventos passados (ex.: ''He was tired because he had worked all day.'').","Com expressões de tempo como ''by the time'', ''before'', ''after'', ''already'', ''just'', ''never'', etc.","Para expressar desejos ou arrependimentos em orações condicionais irreais (ex.: ''I wish I had studied harder.'')."]'::jsonb, '["Usar o Simple Past em vez do Past Perfect quando a ordem dos eventos não está clara.","Esquecer de usar ''had'' com a terceira pessoa do singular (he/she/it) - ''had'' é igual para todos.","Confundir o Past Perfect com o Present Perfect (que se refere ao presente).","Formar o negativo incorretamente: ''had not'' ou ''hadn''t'', nunca ''did not had''.","Uso excessivo do Past Perfect, quando o Simple Past é suficiente para a sequência de eventos."]'::jsonb, '["O Past Perfect é frequentemente usado em reportagens, biografias e relatos históricos para estabelecer a ordem dos fatos.","Na fala cotidiana, os falantes nativos muitas vezes usam o Simple Past em vez do Past Perfect, mas a forma correta é essencial na escrita formal.","A forma contraída ''hadn''t'' é comum na fala e na escrita informal, mas evite em textos muito formais.","Para dar ênfase, pode-se usar ''had really'' ou ''had always'' antes do particípio.","Cuidado com falsos cognatos: ''had'' em inglês não significa ''tinha'' no sentido de posse, mas sim ''tinha feito'' (auxiliar)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

