insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-ee40ab9ef12e', 'en', 'B2', 'The Advanced Passive: Mastering Impersonal and Complex Structures', 'Neste tópico, você vai explorar formas avançadas da voz passiva em inglês, que são essenciais para um nível B2. Você aprenderá a usar a passiva com verbos modais, a estrutura ''have/get something done'' e as passivas impessoais com ''it'' e ''reporting verbs''. Essas estruturas são comuns em textos formais, notícias e situações profissionais, e vão ajudar você a soar mais natural e sofisticado ao se comunicar.', 'A voz passiva avança é formada com o verbo ''to be'' no tempo verbal adequado + o particípio passado do verbo principal. Para verbos modais, use: modal + be + particípio passado (ex: ''must be done''). Para ''have/get something done'', use: have/get + objeto + particípio passado (ex: ''I had my car repaired''). Para a passiva impessoal com ''reporting verbs'', use: it + passive form of reporting verb + that + clause (ex: ''It is said that...'') ou subject + passive reporting verb + to-infinitive (ex: ''He is said to be...'').', '["Para focar na ação em vez do agente, especialmente quando o agente é desconhecido ou óbvio.","Em textos formais e científicos, para dar um tom impessoal.","Com verbos modais para expressar obrigação, permissão ou possibilidade de forma impessoal.","Para descrever processos ou procedimentos, como em manuais ou instruções."]'::jsonb, '["Usar a voz passiva com verbos que não são transitivos (ex: ''The accident was happened'').","Esquecer de usar o particípio passado correto (ex: ''The letter was wrote'').","Confundir ''by'' (agente) com ''with'' (instrumento).","Formar a passiva com ''get'' de maneira informal em contextos formais.","Esquecer de inverter o sujeito e o verbo auxiliar em perguntas na passiva."]'::jsonb, '["Em inglês, a voz passiva é mais comum do que em português, especialmente em textos acadêmicos e jornalísticos.","A passiva com ''get'' é usada em situações informais e para enfatizar o resultado.","Com ''reporting verbs'', a estrutura com ''it'' é mais formal que a estrutura com ''subject''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

