insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b2-754f71201c4b-exercise-05', 'en', 'B2', 'Mixed Reported Speech', 'Combine os diferentes tipos de discurso reportado: afirmações, perguntas e comandos em um contexto complexo.', 'Direct: "I am tired," he said. "Can you help me?" -> He said he was tired and asked if I could help him.', 'She Said: "I will go to the party." Then, "Do you want to come with me?" -> She said that she ______ to the party and asked me ______ with her.', '["would go / if I wanted to go","would go / whether I wanted to go","went / if I wanted to go","will go / if I wanted to go"]'::jsonb, 1, 5, true, 'generated-grammar-en-b2-754f71201c4b')
