insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-68858bdfb168', 'en', 'B2', 'Third and Mixed Conditionals', 'Nesta lição, você vai aprender a usar as condicionais de terceiro tipo e as mistas para falar sobre situações hipotéticas no passado e suas consequências no presente. Essas estruturas são comuns em conversas formais e informais, e dominá-las vai deixar seu inglês muito mais natural e sofisticado.', 'A terceira condicional (third conditional) é formada com ''If + past perfect'' na oração condicional e ''would have + past participle'' na oração principal. Exemplo: ''If I had studied, I would have passed the test.'' As condicionais mistas (mixed conditionals) combinam tempos diferentes: ''If + past perfect'' com ''would + base form'' para falar de um passado hipotético com resultado presente, ou ''If + simple past'' com ''would have + past participle'' para um presente hipotético com resultado passado. Exemplos: ''If I had taken that job, I would be rich now.'' e ''If I were more careful, I wouldn''t have made that mistake.''', '["Para expressar arrependimento ou criticar ações passadas: ''If I had known, I would have acted differently.''","Para falar de situações irreais no passado e suas consequências imaginárias: ''If she had left earlier, she would have caught the train.''","Para misturar tempo: condição no passado, resultado no presente: ''If I had saved money, I could buy a car now.''","Para misturar tempo: condição no presente, resultado no passado: ''If I were more organized, I would have finished the report yesterday.''"]'::jsonb, '["Usar ''would'' na oração com ''if'': ''If I would have studied'' (errado) em vez de ''If I had studied'' (correto).","Confundir a terceira condicional com a segunda: ''If I had a car, I would drive'' (segunda) vs. ''If I had had a car, I would have driven'' (terceira).","Esquecer o ''had'' no past perfect: ''If I studied'' em vez de ''If I had studied''.","Usar a forma errada do verbo no pass participle: ''If I had went'' (errado) em vez de ''If I had gone'' (correto)."]'::jsonb, '["Nas condicionais mistas, preste atenção ao tempo da oração com ''if'' e ao tempo da oração principal para transmitir a relação correta entre passado e presente.","É comum usar ''might have'' ou ''could have'' em vez de ''would have'' para expressar possibilidade ou habilidade no passado.","A inversão pode ser usada em contextos formais: ''Had I known, I would have called'' (equivalente a ''If I had known, I would have called'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b2-68858bdfb168-exercise-01', 'en', 'B2', 'Choose the correct form to complete the third conditional', 'Esta questão testa a formação básica da terceira condicional. A oração com ''if'' usa past perfect, e a oração principal usa would have + past participle.', 'If she ___ (study) harder, she would have passed the exam.', 'Complete the sentence: If she ___ (study) harder, she would have passed the exam.', '["had studied","would study","studied","would have studied"]'::jsonb, 0, 1, true, 'generated-grammar-en-b2-68858bdfb168')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b2-68858bdfb168-exercise-02', 'en', 'B2', 'Identify the mixed conditional (past → present)', 'Nesta questão, você deve identificar uma condicional mista que combina uma condição no passado com um resultado no presente. A estrutura é ''If + past perfect'', ''would + base form''.', 'If I had taken that job, I would be rich now.', 'Which sentence is a mixed conditional (past condition, present result)?', '["If I had taken that job, I would be rich now.","If I take that job, I will be rich.","If I took that job, I would be rich.","If I had taken that job, I would have been rich."]'::jsonb, 0, 2, true, 'generated-grammar-en-b2-68858bdfb168')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

