insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-7a27a80a9156', 'en', 'B2', 'Past Modals for Deduction and Regret', 'Neste tópico, você vai aprender a usar os modal verbs no passado (must have, might have, could have, should have, etc.) para fazer deduções sobre o passado, expressar possibilidade, habilidade e arrependimento. Essas estruturas são essenciais para soar mais natural e sofisticado em inglês, especialmente em situações de discussão de eventos passados.', 'A formação básica é: modal verb + have + past participle. Por exemplo: ''must have gone'', ''might have seen'', ''could have helped'', ''should have studied''. A forma negativa é modal + not + have + past participle (ex: ''shouldn''t have said''). Para perguntas, inverta o modal com o sujeito (ex: ''Could he have known?'').', '["Dedução lógica sobre o passado: ''must have'' (certeza), ''can''t have'' (certeza de que algo não aconteceu)","Possibilidade no passado: ''might have'', ''may have'', ''could have'' (algo era possível, mas não sabemos se aconteceu)","Habilidade no passado: ''could have'' (era capaz, mas não fez)","Conselho ou crítica sobre o passado: ''should have'' / ''shouldn''t have'' (arrependimento ou repreensão)","Necessidade no passado: ''needn''t have'' (algo foi feito, mas não era necessário)"]'::jsonb, '["Usar ''must have'' para possibilidade, em vez de ''might have''","Esquecer de usar o particípio passado após ''have'' (ex: ''must had gone'' em vez de ''must have gone'')","Confundir ''should have'' com ''must have'' (deveria ter feito vs. deve ter feito)","Usar ''can''t have'' no lugar de ''couldn''t have'' em alguns contextos"]'::jsonb, '["A contração ''should''ve'', ''could''ve'', ''might''ve'' é comum na fala e na escrita informal.","Em inglês britânico, às vezes se usa ''must have'' com ''got'' (ex: ''must have got'') em vez de ''must have gotten'' (mais americano).","A entonação pode mudar o significado: ''He could have done it'' pode implicar crítica se a ênfase estiver em ''could''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

