insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-62b4bced7122', 'en', 'B2', 'Argumentative Discourse Markers', 'Vamos explorar os marcadores discursivos usados para estruturar argumentos em inglês. Eles ajudam a conectar ideias, contrastar pontos de vista, adicionar evidências e concluir raciocínios de forma clara e persuasiva.', 'Esses marcadores são palavras ou frases que conectam orações ou parágrafos. Eles podem ser classificados por função: adição (furthermore, moreover, in addition), contraste (however, on the other hand, nevertheless), causa/consequência (therefore, as a result, consequently), exemplificação (for instance, for example, such as), e conclusão (in conclusion, to sum up).', '["Para adicionar informações: Furthermore, o autor reforça seu ponto.","Para introduzir um contraste: However, os dados mostram o oposto.","Para indicar consequência:Therefore, a proposta é viável.","Para dar exemplos: For instance, o estudo de caso ilustra isso.","Para concluir: In conclusion, a evidência é clara."]'::jsonb, '["Usar ''although'' e ''but'' juntos na mesma frase.","Confundir ''however'' (porém) com ''therefore'' (portanto).","Colocar vírgula depois de ''therefore'' no meio da frase.","Usar ''on the other hand'' sem ter apresentado o primeiro ponto.","Usar ''for example'' no final da frase."]'::jsonb, '["Em textos formais, prefira ''furthermore'' e ''moreover''.","''Despite'' e ''in spite of'' são seguidos de substantivo ou gerúndio.","Use ''whereas'' para contrastar duas ideias na mesma frase.","Evite excesso de marcadores; use-os para clareza."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

