insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-34e3b678f4eb', 'en', 'B2', 'Collocations, Register, and Idioms: Sounding Natural in English', 'Neste tópico, vamos explorar como combinações naturais de palavras (collocations), diferentes níveis de formalidade (register) e expressões idiomáticas podem tornar seu inglês mais fluente e autêntico. Você entenderá por que algumas frases soam ''estranhas'' mesmo estando gramaticalmente corretas, e como escolher as palavras certas para cada contexto.', 'Collocations são combinações de palavras que ocorrem juntas com frequência, como ''make a decision'' (em vez de ''do a decision'') ou ''heavy rain'' (em vez de ''strong rain''). Register refere-se ao nível de formalidade: formal (escrita acadêmica), neutro (conversas cotidianas) e informal (gírias e amigos próximos). Idioms são expressões fixas cujo significado não é literal, como ''kick the bucket'' (morrer) ou ''break the ice'' (iniciar uma conversa).', '["Usar ''make a decision'' e ''do homework'' para soar natural em contextos acadêmicos e profissionais.","Escolher ''purchase'' em um e-mail formal, mas ''buy'' em uma conversa com amigos.","Compreender e usar idioms como ''hit the sack'' (ir dormir) em situações informais.","Evitar traduções literais do português, como ''fazer uma pergunta'' (ask a question, não ''make a question'').","Adaptar a linguagem ao público: relatórios, apresentações, e-mails, conversas casuais."]'::jsonb, '["Dizer ''do a mistake'' em vez de ''make a mistake''.","Usar ''get a job'' em contexto muito formal, preferindo ''obtain employment''.","Traduzir ''ter sucesso'' como ''have success'', quando o natural é ''be successful''.","Empregar idioms em situações formais, como ''cut corners'' em um relatório de negócios.","Confundir ''say'' e ''tell'', usando ''say me'' em vez de ''tell me''."]'::jsonb, '["Preste atenção a collocations comuns em inglês acadêmico e profissional.","Observe como nativos usam a língua em diferentes contextos: notícias, filmes, e-mails.","Idioms são importantes, mas use-os com moderação e somente quando apropriado.","Registro não é apenas vocabulário: também envolve gramática, como contrações e phrasal verbs.","Ler e ouvir inglês autêntico ajuda a internalizar combinações naturais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

