insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-5fd1f54bac5f', 'en', 'B2', 'Present Perfect and Present Perfect Continuous', 'Nesta lição, você vai aprender a diferença entre o Present Perfect e o Present Perfect Continuous, dois tempos verbais que expressam ações passadas com relevância no presente. Vamos explorar como usá-los corretamente para descrever experiências, ações concluídas e ações em andamento.', 'Present Perfect: sujeito + have/has + particípio passado. Ex.: ''I have finished.'' ''She has worked.''
Present Perfect Continuous: sujeito + have/has + been + verbo com -ing. Ex.: ''I have been studying.'' ''They have been living here.''', '["Present Perfect é usado para experiências de vida, ações concluídas sem tempo específico.","Present Perfect Continuous enfatiza a duração ou continuidade de uma ação até o presente.","Para ações recentes com efeito presente, costuma-se usar o Present Perfect.","Para ações temporárias que estão em andamento, prefere-se o Present Perfect Continuous."]'::jsonb, '["Usar o Present Perfect com tempo passado definido, como ''yesterday''.","Confundir a forma, por exemplo, ''has been work'' em vez de ''has been working''.","Usar o Present Perfect Continuous com verbos estáticos como ''know'' ou ''want''.","Achar que os dois tempos são intercambiáveis em todas as situações."]'::jsonb, '["O Present Perfect Continuous é frequentemente usado com ''for'' e ''since'' para indicar duração.","O Present Perfect é usado com ''just'', ''already'', ''yet'' para ações recentes ou esperadas.","Alguns verbos, como ''live'', ''work'', ''study'', podem ser usados nos dois tempos, mas com nuances de significado.","Na fala informal, o Present Perfect Continuous é às vezes usado para ações repetidas, como em ''I''ve been getting headaches lately''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

