insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-369a8d43fc5b', 'en', 'B2', 'Advanced Reported Speech', 'No nível B2, você já sabe usar o discurso reportado para afirmar o que alguém disse. Agora vamos aprofundar: lidar com mudanças de tempo, pronomes, palavras de lugar e tempo, além de verbos como ''suggest'', ''insist'', ''apologize'' e estruturas com ''to-infinitive'' e gerúndio. Vamos também explorar o uso de ''say'' vs ''tell'' e como reportar perguntas e comandos de forma natural.', 'No discurso reportado, recuamos o tempo verbal: presente simples vira passado simples, presente contínuo vira passado contínuo, presente perfeito vira passado perfeito, passado simples vira passado perfeito, e ''will'' vira ''would''. Exemplos: ''I am tired'' -> ''She said she was tired.''; ''I have seen it'' -> ''He said he had seen it.''; ''I will call'' -> ''She said she would call.'' Para perguntas, usamos a ordem direta e ''if/whether'' para sim/não: ''Are you ok?'' -> ''She asked if I was ok.'' Para comandos e pedidos, usamos ''tell/ask + to-infinitive'': ''Be quiet!'' -> ''He told us to be quiet.'' Verbos como ''suggest'', ''insist'', ''recommend'' usam gerúndio ou ''that + sujeito + (should) + verbo'': ''I suggest going'' -> ''He suggested going'' ou ''He suggested that we go/should go.''', '["Relatar o que alguém disse em uma conversa, mantendo o sentido original.","Reportar perguntas em inglês, invertendo a ordem das palavras e usando ''if/whether'' para perguntas de sim/não.","Transmitir comandos, pedidos e conselhos usando expressões como ''told someone to'' ou ''asked someone to''.","Usar verbos como ''suggest'' e ''recommend'' para reportar sugestões de forma natural.","Adaptar pronomes, possessivos e expressões de tempo e lugar ao contexto da fala reportada."]'::jsonb, '["Esquecer de recuar o tempo verbal, como em ''She said she is tired'' em vez de ''She said she was tired''.","Usar a ordem de pergunta em perguntas reportadas, como ''She asked where was he'' em vez de ''She asked where he was''.","Confundir ''say'' e ''tell'': usamos ''say something'' e ''tell someone''. Por exemplo, ''She told to me'' está incorreto; o correto é ''She told me''.","Esquecer de mudar pronomes e possessivos, como ''He said, I will do my best'' virando ''He said he would do his best''.","Usar ''say'' com pessoa: ''He said me'' é errado; use ''he told me''.","Em sugestões, usar infinitivo sem ''that'' ou ''should'', como ''He suggested to go'' em vez de ''He suggested going'' ou ''He suggested that we go''."]'::jsonb, '["Com ''say'', usamos ''say to someone'', mas com ''tell'' usamos ''tell someone'' (sem ''to'').","Para relatar perguntas com ''wh-'', usamos a ordem direta: ''She asked where the station was.''","Mudanças de tempo são opcionais se o fato ainda é verdadeiro, mas no B2 é comum recuar sempre.","Existem exceções: se o verbo introdutório está no presente (He says...), não recuamos o tempo.","Para relatar pedidos com ''could'' ou ''would'', usamos ''ask someone to''.","Verbos como ''apologize'', ''insist'', ''admit'' têm padrões próprios: ''apologize for + -ing'', ''insist on + -ing'' ou ''insist that''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

