insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-b2-369a8d43fc5b-exercise-05', 'en', 'B2', 'Say vs Tell', 'Use ''say'' + something, ''say to someone'', e ''tell'' + someone. Não use ''tell to''.', 'He said he was tired. / He told me he was tired.', 'Choose the correct sentence:', '["She said me that she was happy.","She told to me that she was happy.","She told me that she was happy.","She said that she was happy to me."]'::jsonb, 2, 5, true, 'generated-grammar-en-b2-369a8d43fc5b')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-a75ba54e592e', 'en', 'B2', 'Third and Mixed Conditionals: Imagining the Past and Its Present Consequences', 'Nesta lição, você vai aprender a usar as condicionais de terceiro tipo (third conditional) e as condicionais mistas (mixed conditionals) para falar sobre situações hipotéticas no passado e suas consequências no presente ou vice-versa. Essas estruturas são essenciais para expressar arrependimentos, críticas e especulações sobre como as coisas poderiam ter sido diferentes.', 'Third Conditional: If + past perfect, would have + past participle. Exemplo: If I had studied harder, I would have passed the exam. Mixed Conditional (tipo 1): If + past perfect, would + base form. Exemplo: If I had studied harder, I would be a doctor now. Mixed Conditional (tipo 2): If + past simple, would have + past participle. Exemplo: If I were richer, I would have bought that car.', '["Falar sobre eventos passados que não aconteceram e suas consequências imaginárias no passado.","Expressar arrependimento sobre ações passadas que afetam o presente.","Fazer críticas construtivas sobre decisões passadas.","Especular sobre como o presente seria diferente se algo tivesse acontecido no passado.","Falar sobre condições presentes que teriam mudado ações passadas."]'::jsonb, '["Usar ''would'' na cláusula ''if'' (ex.: If I would have known).","Confundir os tempos: usar ''would'' em vez de ''had'' no passado perfeito.","Esquecer o particípio passado após ''have'' em ''would have''.","Misturar os tipos de condicional mista de forma incorreta."]'::jsonb, '["A terceira condicional é frequentemente usada para expressar arrependimento.","Na condicional mista tipo 1, a condição está no passado, mas o resultado é no presente.","Na condicional mista tipo 2, a condição está no presente (ou é geral), mas o resultado é no passado.","O ''if'' pode ser omitido em estruturas formais: ''Had I known, I would have acted differently.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

