insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-5de6edf2032d', 'en', 'B2', 'Past Modals: Degree of Certainty', 'Neste tópico, você vai aprender a usar os verbos modais no passado (must have, might have, could have, can''t have, should have) para expressar diferentes graus de certeza sobre eventos passados. Isso é essencial para fazer suposições, críticas e conselhos sobre o passado de forma natural em inglês.', 'A formação é: modal + have + particípio passado do verbo principal. Exemplos: must have done, might have seen, could have gone, can''t have been, should have studied.', '["Must have: para expressar certeza quase total de que algo aconteceu (dedução lógica).","Might have / may have / could have: para expressar possibilidade no passado (não temos certeza).","Can''t have: para expressar certeza de que algo não aconteceu (impossibilidade).","Should have / ought to have: para expressar crítica ou arrependimento sobre o passado (algo que deveria ter sido feito)."]'::jsonb, '["Usar ''must'' sem ''have'' para passado (ex: ''He must studied'' em vez de ''He must have studied'').","Confundir ''can''t have'' com ''couldn''t have'': ambos são possíveis, mas ''can''t have'' é mais forte.","Usar ''should have'' para expressar possibilidade em vez de crítica.","Usar ''must not have'' para negar uma dedução (o correto é ''can''t have'')."]'::jsonb, '["Lembre-se: ''must have'' e ''can''t have'' são opostos em termos de certeza.","A contração ''should''ve'' é comum na fala, mas na escrita formal use ''should have''.","Para perguntas sobre possibilidade passada, use ''Could he have...?'' ou ''Might she have...?''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

