insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-b2-3024e4505b95', 'en', 'B2', 'Inversion and Emphasis in English', 'Nesta lição, você vai aprender a usar a inversão para dar ênfase em frases em inglês. A inversão é uma ferramenta poderosa para destacar informações, criar impacto e soar mais sofisticado. Vamos explorar quando e como usá-la, especialmente com advérbios negativos e expressões como ''not only'' e ''never''. Além disso, veremos como a inversão é usada em perguntas e em estruturas condicionais.', 'A inversão ocorre quando invertemos a ordem normal sujeito-verbo, geralmente colocando o verbo auxiliar antes do sujeito. Isso acontece em perguntas e em algumas construções enfáticas.

1. Em perguntas: ''Are you coming?'' (normal: You are coming.)
2. Com advérbios negativos ou restritivos no início da frase: ''Never have I seen such a beautiful sunset.'' (Normal: I have never seen...)
3. Com expressões como ''not only'', ''hardly'', ''scarcely'', ''no sooner'': ''Not only did she finish the project, but she also presented it.''
4. Em condicionais sem ''if'': ''Were I you, I would apologize.'' (Equivalente a ''If I were you...'')
5. Com ''so'' ou ''such'' para ênfase: ''So tired was she that she fell asleep immediately.''', '["Para dar destaque a uma informação, especialmente em linguagem formal ou literária.","Em perguntas, para pedir informações.","Com advérbios negativos no início da frase para expressar surpresa ou contraste.","Em frases condicionais para soar mais formal.","Em construções com ''neither/nor'' para concordar com uma negativa."]'::jsonb, '["Usar inversão com advérbios de frequência como ''often'' ou ''usually'' sem necessidade.","Esquecer o auxiliar em inversões com tempos simples (ex.: ''Never I have seen'' em vez de ''Never have I seen'').","Aplicar inversão em frases afirmativas sem um motivo claro, o que soa estranho.","Inverter o sujeito e o verbo principal em vez do auxiliar (ex.: ''Never saw I'' em vez de ''Never did I see'')."]'::jsonb, '["Em inversões com advérbios negativos, usamos o auxiliar ''do'' quando não há outro auxiliar ou modal.","A inversão é mais comum em inglês formal e em textos escritos. Na fala informal, é menos frequente.","Cuidado com a inversão em perguntas: o sujeito vem após o auxiliar ou modal.","Em condicionais com inversão, omitimos ''if'' e invertemos o sujeito e o verbo (ex.: ''Had I known'', ''Should you need'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

