insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-48fd6ba83535', 'es', 'B2', 'Orações Concessivas em Espanhol', 'As orações concessivas são usadas para expressar uma dificuldade, objeção ou condição contrária que não impede a realização da ação principal. No espanhol, elas são introduzidas por conjunções como ''aunque'', ''a pesar de que'', ''por más que'', entre outras. Nesta lição, você aprenderá a formar e usar essas estruturas para enriquecer sua comunicação, especialmente em contextos formais e escritos.', 'As orações concessivas podem ser formadas com:
- ''Aunque'' + verbo no indicativo (fatos reais) ou subjuntivo (hipóteses ou fatos conhecidos): ''Aunque llueve, salgo a correr.'' / ''Aunque llueva, saldré a correr.''
- ''A pesar de que'' + indicativo ou subjuntivo, com uso similar a ''aunque''.
- ''Por más que'' + subjuntivo, para enfatizar esforço inútil: ''Por más que estudie, no apruebo.''
- ''Si bien'' + indicativo, mais formal: ''Si bien es caro, lo compraré.''
- ''Y eso que'' + indicativo, para introduzir uma informação que contradiz a expectativa: ''Llegó tarde, y eso que salió temprano.''
- Também podem ser formadas com gerúndio ou particípio: ''Siendo pobre, es feliz.'' / ''Dicho esto, se fue.''', '["Para expressar contraste inesperado: ''Aunque estaba cansado, fue a la fiesta.''","Para argumentar em textos formais e acadêmicos: ''Si bien la tecnología avanza, la brecha digital persiste.''","Para indicar uma condição que não impede a ação: ''Aunque no tengas dinero, puedes disfrutar de la ciudad.''","Para expressar esforço inútil: ''Por más que lo intento, no consigo recordar su nombre.''"]'::jsonb, '["Usar ''aunque'' com indicativo quando o fato é hipotético: ''Aunque llueve, saldré'' (errado, pois ''saldré'' está no futuro; o correto seria ''Aunque llueva, saldré'').","Confundir ''a pesar de que'' com ''a pesar de'' + infinitivo/possessivo: ''a pesar del frío'' (substantivo) vs. ''a pesar de que hace frío'' (oração).","Usar ''por más que'' com indicativo: ''Por más que lo intento'' (errado; o subjuntivo é obrigatório: ''Por más que lo intente'').","Omissão do subjuntivo em contextos de incerteza após ''aunque''."]'::jsonb, '["Quando a oração concessiva se refere a um fato já conhecido ou certo, usa-se o indicativo; quando se refere a uma hipótese ou fato incerto, usa-se o subjuntivo.","''Aunque'' é a conjunção mais comum. Em registros formais, ''si bien'' e ''aun cuando'' são preferíveis.","A oração concessiva pode aparecer antes ou depois da oração principal.","Outras construções: ''como si'' (comparativa), ''ni aun'' (negativa)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

