insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-42818b489589', 'es', 'B2', 'Antecedentes Relativos No Específicos en Español', 'Vamos explorar como usar pronombres relativos com antecedentes não específicos, como ''lo que'', ''quien'' e ''cual'', para conectar ideias de forma mais sofisticada e natural em espanhol no nível B2.', 'Os antecedentes não específicos são usados quando o substantivo ao qual nos referimos não é claramente definido. Em espanhol, usamos principalmente ''lo que'' para referir a uma ideia ou situação, ''quien'' para pessoas não específicas, e ''el cual/la cual'' (e suas formas plurais) para coisas ou pessoas em registros mais formais. Exemplos: ''Lo que me gusta es viajar'', ''Quien estudia, aprueba'', ''El libro del cual te hablé está agotado''.', '["Referir a uma ideia ou declaração completa: ''Lo que dijiste es importante.''","Referir a pessoas de forma genérica: ''Quien quiera participar, debe inscribirse.''","Referir a coisas ou pessoas com preposições: ''La persona de la cual te hablé.''","Evitar repetir um substantivo mencionado anteriormente: ''No me gustó la película, pero lo que me gustó fue el final.''"]'::jsonb, '["Usar ''que'' em vez de ''lo que'' para referir a uma ideia: ''Dijo que me gusta'' em vez de ''Dijo lo que me gusta''.","Confundir ''quien'' (singular) e ''quienes'' (plural) quando o antecedente é plural.","Usar ''el cual'' sem concordância de gênero e número: ''la cual'', ''los cuales'', ''las cuales''.","Traduzir literalmente ''o que'' como ''el que'' em contextos onde se deve usar ''lo que''."]'::jsonb, '["''Lo que'' é invariável, não muda com gênero ou número.","''Quien'' é usado principalmente em registros escritos ou formais; na fala, às vezes se usa ''el que'' ou ''la que''.","As formas com ''cual'' são mais formais e podem ser precedidas por preposições.","Para expressar ''o que'' em perguntas indiretas, usa-se ''lo que''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

