insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-17a99b3b71be', 'es', 'B2', 'Expresiones de deseo y condición con ''OJALÁ'' y ''COMO SI''', 'Este tópico aborda o uso avançado de ''ojalá'' e ''como si'' para expressar desejos e condições irreais ou hipotéticas em espanhol. Você aprenderá a estrutura correta com indicativo e subjuntivo, os usos específicos e os erros comuns, com exercícios práticos para consolidar o conhecimento.', 'OJALÁ + presente de subjuntivo: para desejos possíveis no presente/futuro. OJALÁ + pretérito imperfeito de subjuntivo: para desejos impossíveis ou improváveis. COMO SI + pretérito imperfeito de subjuntivo: para comparar situações irreais ou hipotéticas. Exemplos: ''Ojalá llueva mañana'' (possível), ''Ojalá tuviera más tiempo'' (improvável), ''Habla como si fuera experto'' (irreal).', '["Expressar desejos possíveis ou prováveis com ''ojalá'' + presente do subjuntivo.","Expressar desejos impossíveis ou improváveis com ''ojalá'' + pretérito imperfeito do subjuntivo.","Fazer comparações hipotéticas com ''como si'' + pretérito imperfeito do subjuntivo.","Usar ''como si'' em estruturas com ''tratar a alguien como si...'' ou ''comportarse como si...''.","Diferenciar entre situações reais (indicativo) e irreais (subjuntivo) em contextos de desejo e comparação."]'::jsonb, '["Usar indicativo após ''ojalá'' (ex: ''Ojalá llueve mañana'' - incorreto).","Usar presente do subjuntivo após ''como si'' (ex: ''como si tenga'' - incorreto).","Confundir ''ojalá que'' com ''ojalá'' (embora ''ojalá que'' seja aceito em alguns registros, é preferível sem ''que'').","Usar condicional simples após ''como si'' (ex: ''como si tendría'' - incorreto)."]'::jsonb, '["Atenção: ''Ojalá'' vem do árabe e significa ''que Deus queira''.","No espanhol coloquial, às vezes se usa indicativo após ''ojalá'' em desejo de menor probabilidade, mas isso é considerado não padrão.","A estrutura ''como si'' exige sempre o pretérito imperfeito do subjuntivo (ou o pretérito pluscuamperfecto do subjuntivo para ações passadas).","Em situações formais, evite a forma ''ojalá y'' (ex: ''ojalá y llueva'') embora seja comum em alguns países."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

