insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-4399b78df8f8', 'es', 'B2', 'Marcadores Argumentativos en Español', 'Este tópico aborda los marcadores argumentativos, que son conectores discursivos esenciales para organizar ideas, contrastar puntos de vista y expresar causa, consecuencia y condición. Dominarlos te permitirá escribir y hablar de manera más persuasiva y estructurada en contextos formales e informales.', 'Los marcadores argumentativos se clasifican en conectores de contraste (pero, sin embargo, no obstante, por otro lado), de causa (porque, ya que, puesto que), de consecuencia (por lo tanto, en consecuencia, así que), de condición (si, siempre que, a menos que) y de orden o adición (primero, además, por último). Se colocan al inicio de la oración o entre cláusulas, y van seguidos de una pausa (coma) cuando inician la frase.', '["Para contrastar ideas: ''Quería salir, pero llovía.''","Para introducir una objeción: ''Sin embargo, hay otro punto de vista.''","Para expresar causa: ''No fui porque estaba enfermo.''","Para señalar consecuencia: ''Estudió mucho; por lo tanto, aprobó.''","Para condicionar una idea: ''Si tienes tiempo, ven a visitarme.''","Para ordenar argumentos: ''Primero, veamos los hechos; además, escuchemos las opiniones; por último, decidamos.''"]'::jsonb, '["Confundir ''sin embargo'' con ''sino'': ''No es caro, sin embargo útil'' (incorrecto; debe ser ''sino útil'').","Usar ''porque'' en lugar de ''por qué'' en preguntas indirectas: ''No sé porque llegó tarde'' (correcto: ''No sé por qué llegó tarde'').","Omitir la coma después de conectores al inicio: ''Sin embargo no estoy de acuerdo'' (correcto: ''Sin embargo, no estoy de acuerdo'').","Usar ''sino'' como conjunción adversativa cuando no hay negación previa: ''Quiero ir, sino que no puedo'' (correcto: ''Quiero ir, pero no puedo'')."]'::jsonb, '["En español, los marcadores de contraste como ''no obstante'' y ''sin embargo'' son más formales que ''pero''.","La coma después de conectores al inicio de la oración es obligatoria en la escritura formal.","Algunos conectores, como ''puesto que'' y ''ya que'', son sinónimos de ''porque'' pero se usan en un registro más culto."]'::jsonb, 0, true)
