insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-dd221ca454b4', 'es', 'B2', 'Perfect and Imperfect Subjunctive in Spanish', 'O subjuntivo é um modo verbal essencial em espanhol para expressar dúvida, desejo, emoção, opinião negativa, entre outros. No nível B2, você vai aprofundar o uso dos tempos perfeitos e imperfeitos do subjuntivo, que permitem falar sobre ações passadas, situações hipotéticas ou irreais, e expressar cortesia. Dominar essas formas vai deixar sua comunicação mais precisa e natural.', 'O pretérito imperfeito do subjuntivo (ou simplesmente imperfeito) é formado a partir da terceira pessoa do plural do pretérito perfeito simples (indefinido), removendo a terminação ''-ron'' e adicionando as desinências ''-ra'', ''-ras'', ''-ra'', ''-ramos'', ''-rais'', ''-ran'' (ou ''-se'', ''-ses'', ''-se'', ''-semos'', ''-seis'', ''-sen'', menos comum na América). Por exemplo: ''hablaron'' -> ''hablara/hablase''. O pretérito perfeito composto do subjuntivo (ou perfeito) é formado pelo presente do subjuntivo do verbo ''haber'' (haya, hayas, haya, hayamos, hayáis, hayan) + particípio passado do verbo principal. Por exemplo: ''haya hablado''. Essas formas são usadas em orações subordinadas e em expressões fixas.', '["Dúvida ou negação sobre fatos passados: ''No creo que él haya llegado a tiempo.''","Desejo ou emoção em relação a situações irreais ou hipotéticas: ''Ojalá hubiera estudiado más para el examen.''","Expressões impessoais de opinião negativa ou valorativa: ''Era importante que todos estuvieran presentes.''","Condições irreais com ''si'': ''Si tuviera dinero, viajaría por el mundo.''","Cortesia e sugestões: ''Quisiera pedirte un favor.''","Em orações relativas com antecedente indefinido ou negado: ''Busco un libro que explique bien este tema.''"]'::jsonb, '["Confundir o imperfeito do subjuntivo com o condicional em orações com ''si'': ''Si tendría tiempo'' em vez de ''Si tuviera tiempo''.","Usar o presente do subjuntivo no lugar do imperfeito em contextos passados: ''Esperaba que él venga'' em vez de ''Esperaba que él viniera''.","Empregar o subjuntivo depois de verbos como ''creer'' e ''opinar'' em frases afirmativas: ''Creo que él venga'' em vez de ''Creo que él viene''.","Omissão do ''haya'' no perfeito: ''No creo que él hablado'' em vez de ''No creo que él haya hablado''."]'::jsonb, '["Em espanhol, o subjuntivo é usado em orações subordinadas iniciadas por ''que'' quando o verbo principal expressa vontade, emoção, dúvida, etc.","O imperfeito do subjuntivo tem duas formas equivalentes (-ra e -se). A forma em -ra é mais comum na América.","Em orações condicionais irreais, a combinação clássica é: si + imperfeito do subjuntivo, condicional simples. Para referir-se ao passado: si + mais-que-perfeito do subjuntivo, condicional composto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

