insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-c74562ad60cd', 'es', 'B2', 'Orações Concessivas em Espanhol (Aunque, A pesar de que, etc.)', 'As orações concessivas são usadas para expressar uma dificuldade, objeção ou condição contrária que não impede a realização da ação principal. Em espanhol, os conectores mais comuns são ''aunque'', ''a pesar de que'', ''por más que'', ''si bien'', entre outros. Nesta lição, você aprenderá a formar e usar essas estruturas para enriquecer seu discurso e expressar ideias de oposição com nuances.', 'As orações concessivas podem ser formadas com diferentes conectores: Aunque + verbo (indicativo ou subjuntivo) / A pesar de que + verbo (indicativo ou subjuntivo) / Por más que + verbo (subjuntivo) / Si bien + verbo (indicativo). A escolha do modo verbal depende do grau de certeza ou realidade do fato. Use o indicativo quando a informação é factual; use o subjuntivo quando a informação é hipotética, duvidosa ou desconhecida.', '["Para expressar contraste ou oposição entre duas ideias.","Para indicar que algo acontece apesar de um obstáculo.","Para mostrar que uma condição não é suficiente para impedir um resultado.","Para introduzir concessões retóricas em argumentações.","Para expressar frustração ou limitação em contextos informais."]'::jsonb, '["Usar o subjuntivo depois de ''aunque'' quando o fato é real: ''Aunque estoy cansado, iré'' (não ''esté'').","Confundir ''a pesar de'' (preposição seguida de substantivo ou infinitivo) com ''a pesar de que'' (conjunção seguida de verbo conjugado).","Usar ''por más que'' com indicativo: sempre exige subjuntivo.","Trocar ''si bien'' por ''si aunque''.","Esquecer que ''aunque'' pode ser substituído por ''aun'' ou ''ni siquiera'' em algumas expressões."]'::jsonb, '["''Aunque'' é o conector mais versátil e pode ser usado tanto com indicativo quanto com subjuntivo.","''A pesar de que'' é um pouco mais formal que ''aunque''.","''Por más que'' expressa esforço inútil: ''Por más que estudio, no apruebo''.","''Si bien'' é usado principalmente em textos formais e significa ''embora''.","As orações concessivas podem aparecer antes ou depois da oração principal.","Quando a oração concessiva vem antes, usa-se vírgula."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

