insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-553218c42c66', 'es', 'B2', 'Antecedentes Relativos No Específicos en Español', 'Nesta lição, vamos explorar os antecedentes relativos não específicos, como ''lo que'', ''quien'', ''cualquier cosa que'' e ''donde'', que são usados para se referir a algo indefinido ou não específico. Você aprenderá a usá-los para expressar ideias gerais, fazer perguntas abertas e conectar ideias de forma mais sofisticada, essencial para um nível B2.', 'Os antecedentes relativos não específicos são pronomes ou advérbios que introduzem orações relativas sem um antecedente explícito ou definido. Eles podem ser:
- ''lo que'' (o que, aquilo que) para referir a uma ideia ou situação.
- ''quien'' (quem) para pessoas, geralmente sem antecedente específico.
- ''cualquier cosa que'' (qualquer coisa que) para objetos ou ideias indefinidas.
- ''donde'' (onde) para lugares.
Eles são formados pela combinação de um pronome ou advérbio relativo e podem ser usados como sujeito ou objeto da oração.', '["Para expressar generalizações: ''Lo que me gusta de este país es la gente.''","Para fazer perguntas indiretas: ''No sé quién vendrá a la fiesta.''","Para referir a lugares: ''Prefiero viajar a donde haya playa.''","Para dar ênfase a uma ideia: ''Cualquier cosa que digas, no te creeré.''"]'::jsonb, '["Não confundir ''lo que'' com ''que'' quando o antecedente é uma ideia inteira.","Não omitir o artigo ''lo'' antes de ''que'' quando o referente é uma oração.","Não usar ''que'' em vez de ''quien'' para pessoas sem antecedente.","Não esquecer o subjuntivo em orações relativas com antecedente indefinido."]'::jsonb, '["O subjuntivo é frequentemente usado após antecedentes não específicos para indicar incerteza ou falta de definição.","Em situações formais, ''quien'' pode ser usado sem antecedente, equivalente a ''aquel que''.","''Donde'' pode ser usado sem antecedente para indicar um lugar indeterminado."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

