insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-30faa4e9c639', 'es', 'B2', 'La secuencia de tiempos verbales en español', 'Este tópico aborda a sequência de tempos verbais em espanhol, fundamental para expressar relações temporais complexas em discursos e textos. Você aprenderá a combinar tempos passados, presentes e futuros para narrar eventos, expressar hipóteses e descrever ações simultâneas ou anteriores, melhorando sua fluência e precisão.', 'A sequência de tempos verbais refere-se à escolha correta do tempo verbal em orações subordinadas com base no tempo da oração principal. No passado, usamos o pretérito pluscuamperfecto para ações anteriores a outra ação passada, o indefinido para ações concluídas, e o imperfecto para ações em progresso ou habituais. Para o futuro, usamos o condicional para expressar ações futuras em relação a um passado. Exemplos: ''Dijo que había terminado'' (passado do passado), ''Pensé que vendría'' (futuro do passado), ''Cuando llegó, ya habíamos salido'' (ação anterior).', '["Narrar eventos passados em ordem cronológica: ''Cuando llegué, ella ya había salido''.","Expressar uma ação futura em relação a um momento passado: ''Me prometió que llamaría''.","Descrever ações simultâneas no passado: ''Mientras estudiaba, sonó el teléfono''.","Expressar hipóteses ou condições irreais: ''Si hubiera sabido, habría venido''.","Relatar discursos indiretos no passado: ''Dijo que estaba cansado''."]'::jsonb, '["Usar o presente do subjuntivo após um verbo no passado: ''Dijo que venga'' (incorreto) em vez de ''Dijo que viniera''.","Confundir pretérito indefinido e imperfecto em narrações: ''Cuando era joven, viajé a España'' (correto), mas ''Cuando fui joven...'' (incorreto).","Usar o condicional em vez do subjuntivo em estruturas com ''si'': ''Si tendría dinero, compraría'' (incorreto) em vez de ''Si tuviera dinero, compraría''.","Usar o presente após um condicional: ''Me dijo que viene'' (incorreto) em vez de ''Me dijo que vendría''."]'::jsonb, '["O pretérito pluscuamperfecto é formado com o imperfecto de ''haber'' + particípio passado.","O condicional simples expressa ações futuras em relação ao passado, enquanto o condicional composto expressa ações hipotéticas concluídas.","A sequência de tempos é crucial para narrativas coesas e para o discurso indireto.","Pratique a combinação de tempos em contextos reais, como contar histórias ou relatar notícias."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

