insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-2c2c89b7a6c8', 'es', 'B2', 'Orações Concessivas em Espanhol (Aunque, A pesar de que, Por más que)', 'As orações concessivas expressam uma concessão, ou seja, apresentam uma ideia que se opõe à ação principal, mas não a impede. Em espanhol, existem várias conjunções e locuções para introduzi-las, como ''aunque'', ''a pesar de que'', ''por más que'', entre outras. Nesta unidade, você aprenderá a usá-las corretamente, distinguindo entre os modos indicativo e subjuntivo, e a evitar erros comuns.', 'As orações concessivas são formadas com uma conjunção ou locução concessiva seguida de uma oração com verbo no indicativo ou no subjuntivo. A escolha do modo depende do grau de certeza ou realidade do que se expressa. Principais conectores: aunque, a pesar de que, por más que, si bien, etc. Exemplos: ''Aunque llueve, salgo a correr'' (indicativo, fato real); ''Aunque llueva, saldré a correr'' (subjuntivo, hipótese).', '["Para expressar contraste: ''Aunque es caro, lo compré.''","Para expressar condição hipotética: ''Aunque tuviera dinero, no viajaría.''","Para expressar obstáculo superado: ''Por más que intento, no lo logro.''","Para conceder um ponto antes de contra-argumentar: ''Si bien es difícil, es posible.''","Para expressar uma restrição: ''A pesar de que estaba cansado, terminó el trabajo.''"]'::jsonb, '["Usar sempre o indicativo: ''Aunque llueve, saldré'' (errado, se for hipótese).","Confundir ''aunque'' com ''pero'': ''Aunque es tarde, pero llegaré'' (errado).","Usar ''a pesar de'' sem ''que'': ''A pesar de que'' é locução; ''a pesar de'' é seguido de substantivo ou infinitivo.","Esquecer o subjuntivo após ''por más que'' quando o resultado é incerto."]'::jsonb, '["''Aunque'' pode ser substituído por ''a pesar de que'' em muitos contextos, mas ''aunque'' é mais versátil.","Com ''aunque'' no indicativo, a informação é dada como fato; no subjuntivo, como hipótese.","Na linguagem informal, é comum usar ''aunque'' com indicativo mesmo em situações hipotéticas, mas para o B2, é importante dominar a distinção formal."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

