insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-678e367e42b6', 'es', 'B2', 'Antecedentes Relativos No Específicos', 'Nesta lição, você vai aprender a usar pronomes relativos com antecedentes indefinidos ou não específicos, como ''lo que'', ''quien'', ''cual'' e ''cuyo''. Esse uso é comum para expressar ideias gerais, opiniões e conceitos abstratos, e é essencial para alcançar um nível B2 em espanhol.', 'Em espanhol, os pronomes relativos podem se referir a um antecedente que não é uma pessoa ou coisa específica. Os principais são:
- ''Lo que'': usado para referir-se a uma ideia, situação ou conceito (ex.: ''No entiendo lo que dices.'').
- ''Quien/quienes'': usado para pessoas, mas quando o antecedente é indefinido ou genérico (ex.: ''Quien estudia, aprueba.'').
- ''El cual/la cual/los cuales/las cuales'': usado para coisas ou pessoas, mas com antecedente não específico quando precedido de preposição (ex.: ''La razón por la cual me fui.'').
- ''Cuyo/cuya/cuyos/cuyas'': usado para indicar posse, com antecedente não específico (ex.: ''Busco un libro cuyo autor sea brasileño.'').
A escolha do pronome depende da função sintática e se o antecedente é pessoa, coisa ou ideia.', '["Para referir-se a uma ideia ou situação geral: ''Lo que me gusta de este país es la comida.''","Para expressar uma generalização sobre pessoas: ''Quien mal anda, mal acaba.''","Para introduzir uma explicação com preposição: ''No hay razón por la cual debas preocuparte.''","Para expressar posse com antecedente indefinido: ''Necesito un consejo cuyo valor sea incalculable.''","Para conectar frases com ''todo lo que'' (tudo o que): ''Haré todo lo que pueda.''"]'::jsonb, '["Usar ''que'' em vez de ''lo que'' quando o antecedente é uma ideia: ''No entiendo que dices'' (errado) vs ''No entiendo lo que dices'' (correto).","Confundir ''quien'' com ''que'' para pessoas: ''El hombre quien vino'' (errado) vs ''El hombre que vino'' (correto, porque é específico); ''Quien vino, se fue'' (correto para genérico).","Esquecer a preposição antes de ''el cual'': ''La razón que me fui'' (errado) vs ''La razón por la cual me fui'' (correto).","Usar ''cuyo'' sem concordância: ''El libro cuyo autor'' (correto) vs ''El libro cuya autor'' (errado)."]'::jsonb, '["Diferente do português, em espanhol, ''lo que'' é invariável e nunca concorda com o antecedente.","''Quien'' é usado com antecedentes indefinidos; para específicos, usa-se ''que''.","O uso de ''el cual'' é mais formal; na fala cotidiana, ''que'' é mais comum.","Cuidado com a concordância de ''cuyo'' com o substantivo possuído, não com o possuidor."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

