insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-1ee20e7724f2', 'es', 'B2', 'Secuencia temporal en español: del pasado al futuro', 'Nesta lição, você vai aprender a combinar diferentes tempos verbais em espanhol para narrar eventos de forma lógica e expressar relações de anterioridade, simultaneidade e posterioridade. Vamos explorar como usar o pretérito perfecto, indefinido, imperfecto, pluscuamperfecto, condicional e futuro, prestando atenção à sequência temporal em contextos complexos.', 'A sequência temporal se constrói escolhendo o tempo verbal adequado para cada ação, considerando sua relação com o momento da fala ou com outra ação. Estruturas-chave incluem:
- Para ações anteriores a um ponto no passado: pretérito pluscuamperfecto (había + participio).
- Para ações simultâneas em um contexto passado: pretérito imperfecto (cantaba) ou gerúndio (estaba cantando).
- Para ações posteriores a um ponto no passado: condicional (cantaría) ou ir a + infinitivo no pasado.
- Em narrações, usa-se indefinido para eventos principais e imperfecto para descrições ou ações de fundo.
- Para planos futuros: futuro simple (cantaré) ou ir a + infinitivo.', '["Narrar uma história contando fatos em sequência usando indefinido e imperfecto.","Expressar que uma ação passada ocorreu antes de outra: pluscuamperfecto.","Fazer previsões ou promessas: futuro simple.","Falar de planos: ir a + infinitivo no presente ou futuro.","Expressar consequências hipotéticas no passado: condicional composto (habría + participio)."]'::jsonb, '["Usar indefinido em vez de imperfecto para ações contínuas ou habituais no passado.","Confundir o uso de ''estaba haciendo'' (imperfecto) com ''hice'' (indefinido) para ações completadas.","Esquecer o pluscuamperfecto quando há duas ações passadas: ''Cuando llegué, ya había salido''.","Usar futuro no discurso indireto: ''Dijo que vendrá'' deve ser ''Dijo que vendría'' (condicional).","Confundir ''había hecho'' com ''hube hecho'' (este último é raro em espanhol moderno)."]'::jsonb, '["Em espanhol, o pretérito imperfecto é usado para descrever o cenário em narrações, enquanto o indefinido relata os eventos principais.","O condicional é frequentemente usado para expressar probabilidade no passado: ''Serían las diez''.","Para falar de ações futuras em relação ao passado, usa-se condicional simples ou composto.","A combinação ''cuando + indefinido + pluscuamperfecto'' é comum para indicar anterioridade."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

