insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-7ea45f727ae7', 'es', 'B2', 'Condicionales irreales en español', 'Los condicionales irreales expresan situaciones hipotéticas, imposibles o contrarias a la realidad. En español, se construyen con ''si'' + imperfecto de subjuntivo y el condicional simple. Son esenciales para hablar de deseos, consejos y situaciones imaginarias.', 'Para formar el condicional irreal, usa la estructura: ''Si + [imperfecto de subjuntivo] + [condicional simple]''. Por ejemplo: ''Si tuviera más tiempo, viajaría más''. El imperfecto de subjuntivo se forma desde la tercera persona del plural del pretérito indefinido, quitando ''-ron'' y añadiendo ''-ra'', ''-ras'', ''-ra'', ''-ramos'', ''-rais'', ''-ran''. El condicional simple se forma con el infinitivo + ''-ía'', ''-ías'', ''-ía'', ''-íamos'', ''-íais'', ''-ían''.', '["Para hablar de situaciones imaginarias: Si yo fuera rico, compraría un yate.","Para dar consejos en forma hipotética: Si yo fuera tú, estudiaría más.","Para expresar deseos: Si pudiera, viviría en la playa.","Para hablar de hechos poco probables en el presente o futuro: Si lloviera, nos quedaríamos en casa."]'::jsonb, '["Usar el condicional en la cláusula con ''si'': *Si tendría tiempo, iría* (correcto: Si tuviera tiempo, iría).","Usar el presente en la cláusula con ''si'': *Si tengo tiempo, iría* (correcto: Si tuviera tiempo, iría).","Olvidar el acento en las terminaciones del condicional: *viajaria* (correcto: viajaría).","Confundir el imperfecto de subjuntivo con el presente de subjuntivo: *Si haga sol, saldremos* (correcto: Si hiciera sol, saldríamos)."]'::jsonb, '["El condicional irreal se usa para situaciones contrarias a los hechos o poco probables.","Existe también el condicional compuesto para situaciones pasadas: Si hubiera sabido, habría ido.","La forma en ''-ra'' es más común que la forma en ''-se'' en el español moderno.","En lenguaje coloquial, a veces se usa el imperfecto de indicativo, aunque no es normativo: Si tenía dinero, compraba (valor informal).","Las oraciones condicionales irreales pueden invertir el orden: Viajaría más si tuviera tiempo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

