insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-4be8cff31d25', 'es', 'B2', 'Reported Speech in the Past: Mastering Spanish Indirect Speech', 'Neste tópico, você vai aprender a usar o discurso indireto (estilo indirecto) no passado em espanhol. Vamos focar nas mudanças verbais e nos ajustes necessários para relatar o que alguém disse, perguntou ou pediu, com foco em contextos passados. Você verá como transformar frases diretas em indiretas, considerando os tempos verbais e os pronomes.', 'Para formar o discurso indireto no passado, seguimos estas regras principais: 1) O verbo introdutor (decir, preguntar, pedir, etc.) geralmente está no pretérito indefinido (dijo, preguntó) ou pretérito imperfeito (decía, preguntaba). 2) Os tempos verbais sofrem um recuo: presente vira pretérito imperfeito, pretérito perfeito vira pretérito pluscuamperfecto, futuro vira condicional, e o imperativo vira pretérito imperfeito do subjuntivo (ou presente do subjuntivo, dependendo da estrutura). 3) Os pronomes pessoais, possessivos e demonstrativos mudam para refletir o novo contexto. 4) Expressões de tempo e lugar também mudam (por exemplo, ''hoy'' vira ''aquel día'', ''mañana'' vira ''el día siguiente'').', '["Para relatar o que alguém disse em uma conversa passada.","Para transmitir notícias ou informações ouvidas de outra pessoa.","Para contar histórias ou narrar eventos que envolvem falas.","Para reproduzir perguntas feitas no passado (discurso indireto interrogativo).","Para expressar pedidos ou ordens transmitidos indiretamente."]'::jsonb, '["Não ajustar o tempo verbal (ex.: ''Dijo que está cansado'' em vez de ''Dijo que estaba cansado'').","Não alterar os pronomes (ex.: ''Me dijo que me llamarás'' confundindo as pessoas).","Confundir a mudança do futuro para o condicional (ex.: ''Dijo que vendrá'' em vez de ''Dijo que vendría'').","Esquecer de mudar as expressões de tempo (ex.: ''hoy'' por ''aquel día'')."]'::jsonb, '["Atenção: Se o verbo introdutor está no presente (dice, pregunta), o tempo verbal na oração subordinada não muda.","Nas perguntas indiretas, não se usa ponto de interrogação e a ordem das palavras é afirmativa.","Para ordens e pedidos, usa-se ''que'' + subjuntivo (ex.: ''Me dijo que viniera'').","Lembre-se de que o pretérito indefinido e o pretérito perfeito no discurso direto geralmente viram pretérito pluscuamperfecto no indireto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4be8cff31d25-exercise-01', 'es', 'B2', 'Transformação de presente para passado', 'Quando o verbo introdutor está no passado, o presente do indicativo vira pretérito imperfeito do subjuntivo ou indicativo, dependendo da estrutura. Aqui usamos indicativo.', 'Directo: ''Estoy cansado.'' / Indirecto: ''Dijo que estaba cansado.''', 'Transforme a frase para o discurso indireto: ''Marta dijo: "Tengo hambre."''', '["Marta dijo que tiene hambre.","Marta dijo que tenía hambre.","Marta dijo que tendrá hambre.","Marta dijo que ha tenido hambre."]'::jsonb, 1, 1, true, 'generated-grammar-es-b2-4be8cff31d25')
