insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-967440d291b2', 'es', 'B2', 'Nominalización y Estructura de la Información', 'A nominalização é um recurso que transforma verbos ou adjetivos em substantivos, permitindo reorganizar a informação na frase. Em espanhol, é muito comum em contextos formais e acadêmicos para tornar o discurso mais conciso e elegante. Nesta lição, você aprenderá a usar a nominalização para melhorar a fluidez e a coesão dos seus textos.', 'Para nominalizar um verbo, adiciona-se sufixos como -ción, -miento, -ancia, -aje, entre outros. Por exemplo: ''investigar'' → ''investigación'', ''desarrollar'' → ''desarrollo'' (com mudança ortográfica), ''importar'' → ''importancia''. Adjetivos podem virar substantivos com -idad, -eza, -ura: ''rápido'' → ''rapidez'', ''bello'' → ''belleza''. A escolha do sufixo depende da terminação do verbo/adjetivo e de regras de derivação.', '["Para resumir ou generalizar uma ação: ''La creación de empleo es prioridad.''","Para evitar repetições: ''La construcción del puente duró años. La demora fue criticada.''","Para dar ênfase ao resultado ou processo: ''La transformación digital está en curso.''","Em títulos e manchetes: ''Aprobación de la ley genera debate.''","Para conectar ideias de forma mais formal: ''La falta de recursos impide el avance.''"]'::jsonb, '["Usar sufixo incorreto: ''explicación'' (não ''explicimiento''), ''crecimiento'' (não ''crecición'').","Confundir substantivo com adjetivo: ''La importante de la educación'' (deveria ser ''la importancia'').","Exagerar a nominalização em contexto informal, tornando o texto artificial.","Esquecer de ajustar o artigo e a concordância: ''El análisis de los datos'' (não ''los análisis'' se for singular)."]'::jsonb, '["A nominalização é uma característica típica do registro formal, mas também aparece na mídia.","Muitos substantivos derivados mantêm a ortografia original (ex: ''creer'' → ''creencia''), exigindo atenção.","A estrutura da frase pode mudar completamente, mas o significado é preservado.","A prática leva à naturalidade: não force a nominalização se a construção verbal for mais clara."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

