insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-1db002f838f3', 'es', 'B2', 'Condicionales Irreales en Español', 'Neste tópico, você vai aprender a usar as orações condicionais irreais (ou impossíveis) em espanhol. Essas estruturas expressam situações hipotéticas que não são reais ou que são improváveis. Vamos focar no segundo e terceiro condicional, que são usados para falar de situações presentes, passadas e futuras imaginárias.', 'Segundo condicional (presente/futuro hipotético): Se + pretérito imperfecto de subjuntivo + condicional simples. Exemplo: ''Si tuviera más tiempo, viajaría más.'' Terceiro condicional (passado hipotético): Se + pretérito pluscuamperfecto de subjuntivo + condicional compuesto. Exemplo: ''Si hubiera sabido, habría venido antes.''', '["Falar de situações imaginárias no presente ou futuro (ex.: ''Si ganara la lotería, compraría una casa.'').","Expressar conselhos ou desejos hipotéticos (ex.: ''Si yo fuera tú, estudiaría más.'').","Lamentar ações passadas não realizadas (ex.: ''Si hubiera estudiado, habría pasado el examen.'').","Imaginar consequências diferentes de eventos passados (ex.: ''Si no hubiera llovido, habríamos ido a la playa.'')."]'::jsonb, '["Usar o condicional na oração com ''si'' (ex.: ''Si tendría tiempo, iría'' deve ser ''Si tuviera tiempo, iría'').","Confundir o segundo e o terceiro condicional em relação ao tempo (presente vs. passado).","Esquecer a concordância de tempos entre a prótase e a apódose.","Usar o presente do indicativo no terceiro condicional (ex.: ''Si sabía, habría ido'' deve ser ''Si hubiera sabido, habría ido'')."]'::jsonb, '["Em espanhol, o pretérito imperfecto de subjuntivo tem duas formas: ''-ra'' e ''-se'' (ex.: ''tuviera'' ou ''tuviese''). Ambas são corretas.","O condicional composto é formado pelo verbo ''haber'' no condicional simples (habría, habrías...) + particípio.","Podemos usar ''como si'' (como se) para fazer comparações hipotéticas, e neste caso também usamos o subjuntivo (ex.: ''Habla como si supiera todo'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

