insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-c18f8afa4b0d', 'es', 'B2', 'El estilo indirecto en pasado: reportando lo que otros dijeron', 'Neste tópico, vamos explorar o estilo indireto (ou discurso reportado) no passado em espanhol. Você aprenderá a transformar falas diretas em relatos, ajustando tempos verbais, pronomes e expressões de tempo e lugar. Esta habilidade é essencial para narrar conversas, contar histórias e transmitir informações de forma precisa.', 'Para formar o estilo indireto no passado, geralmente usamos um verbo introdutor no passado (como ''dijo'', ''preguntó'', ''pidió'') e fazemos ajustes nos tempos verbais: o presente do indicativo muda para pretérito imperfecto (ex: ''dice'' -> ''decía'', ''quiere'' -> ''quería''), o pretérito perfeito simples (pretérito indefinido) muda para pretérito pluscuamperfecto (ex: ''compró'' -> ''había comprado''), o futuro simples muda para condicional simples (ex: ''comprará'' -> ''compraría''), e o presente do subjuntivo muda para pretérito imperfecto do subjuntivo (ex: ''quiera'' -> ''quisiera''). Além disso, pronomes e advérbios de tempo e lugar mudam: ''yo'' -> ''él/ella'', ''mi'' -> ''su'', ''ahora'' -> ''entonces'', ''hoy'' -> ''aquel día'', ''aquí'' -> ''allí''. Exemplo direto: "Estoy cansado" -> indireto: "Dijo que estaba cansado".', '["Relatar o que alguém disse em uma conversa, mantendo o sentido original.","Narrar histórias ou notícias, reportando falas de personagens.","Transmitir perguntas feitas por outras pessoas, usando ''si'' para perguntas de sim/não e palavras interrogativas para perguntas abertas.","Reportar pedidos, ordens ou sugestões usando ''que'' + subjuntivo (ex: ''Me pidió que lo ayudara'').","Indicar o que alguém pensou, acreditou ou soube no passado, com verbos como ''pensar'', ''creer'', ''saber''."]'::jsonb, '["Não ajustar o tempo verbal, por exemplo, manter ''está'' em vez de ''estaba'' após ''dijo''.","Esquecer de mudar os pronomes, como usar ''yo'' em vez de ''él'' no relato.","Confundir o uso de ''decir que'' com ''decir de'' (o correto é ''decir que'').","Em perguntas indiretas, omitir a inversão do sujeito ou o ''si'' para perguntas fechadas.","Usar o futuro simples em vez do condicional em relatos futuros do passado."]'::jsonb, '["Na linguagem informal oral, é comum não fazer todos os ajustes de tempo, mas na escrita formal é esperado.","Alguns verbos introdutores: ''decir'', ''comentar'', ''explicar'', ''afirmar'', ''preguntar'', ''pedir'', ''ordenar'', ''sugerir''.","Atenção à mudança de ''este'' para ''ese'' e de ''aquí'' para ''allí''.","Para ordens, usamos ''que'' + subjuntivo; por exemplo: ''Me dijo que viniera''.","Recorde que o pretérito perfecto composto (he comprado) muda para pluscuamperfecto (había comprado)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

