insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-b8888ff0cad2', 'es', 'B2', 'Antecedentes relativos no específicos: el que, lo que, quien, donde', 'Nesta lição, você vai aprender a usar pronomes relativos sem antecedente específico, como ''el que'', ''lo que'', ''quien'' e ''donde'', para criar frases mais fluidas e naturais em espanhol. Esses pronomes são essenciais para evitar repetições e conectar ideias de forma elegante. Vamos explorar como usá-los em diferentes contextos e evitar erros comuns.', 'Em espanhol, os pronomes relativos podem ter um antecedente explícito (ex: ''El libro que leí'') ou não específico. Quando o antecedente não é nomeado, usamos formas como: ''el que'', ''la que'', ''lo que'', ''los que'', ''las que'' (equivalente a ''the one(s) that'' em inglês), ''quien'' (who), ''donde'' (where). Exemplos: ''Lo que me gusta es viajar'' (O que eu gosto é viajar), ''Quien estudia aprueba'' (Quem estuda passa), ''Vivo donde hay mar'' (Vivo onde há mar). A escolha depende do gênero (masculino/feminino) e número (singular/plural) do referente implícito, ou do uso neutro com ''lo''.', '["Para se referir a uma coisa ou situação geral: ''Lo que necesitas es descansar''.","Para se referir a uma pessoa ou grupo de pessoas de forma indefinida: ''Quien llega tarde se pierde''.","Para indicar lugar sem especificar: ''Voy donde me reciban''.","Para enfatizar ''aquele(s) que'' ou ''aquilo que'': ''El que quiera puede venir''.","Em expressões fixas como ''lo que sea'', ''quien sabe''."]'::jsonb, '["Usar ''que'' sem artigo ou antecedente: ''Que necesitas es descansar'' (incorreto). O correto é ''Lo que necesitas...''.","Confundir ''quien'' e ''que'' para pessoas: ''Que estudia aprueba'' (incorreto). Use ''Quien estudia aprueba''.","Esquecer a concordância de gênero e número: ''Las que quieran pueden venir'' (correto), ''La que quieran'' (incorreto).","Usar ''donde'' para tempo em vez de ''cuando'': ''Donde llegué, ya había salido'' (incorreto). O correto é ''Cuando llegué...''."]'::jsonb, '["Os pronomes ''el que'', ''la que'', etc., podem ser substituídos por ''quien'' quando se referem a pessoas e em estilo formal: ''Quien estudia aprueba''.","''Lo que'' é neutro e invariável, usado para ideias, fatos ou ações.","''Donde'' é usado somente para lugares; para tempo, use ''cuando''.","Em perguntas indiretas, ''qué'' é usado em vez de ''lo que'': ''No sé qué quiero'' (não ''lo que quiero'').","Aprenda expressões como ''lo que sea'' (seja o que for) e ''quienquiera'' (quem quer que seja) para ampliar seu vocabulário."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

