insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-4e4909674900', 'es', 'B2', 'El Estilo Indirecto en Español: Cómo Reportar lo que Dijeron', 'Nesta lição, você aprenderá a usar o estilo indireto (ou discurso reportado) para relatar o que alguém disse, perguntou ou pediu. Vamos focar nas transformações verbais e pronominais mais comuns, especialmente ao passar do presente para o passado, e como aplicar isso em situações do dia a dia, como conversas informais, entrevistas e narrativas.', 'No estilo indireto, geralmente usamos um verbo introdutor (como ''dijo'', ''preguntó'', ''pidió'') seguido de ''que'' para orações declarativas. Os tempos verbais recuam: o presente vira pretérito imperfeito, o pretérito perfeito vira pretérito pluscuamperfecto, o futuro (ir a + infinitivo) vira ''iba a + infinitivo'', e o condicional permanece. Os pronomes pessoais e possessivos mudam de acordo com a perspectiva de quem relata. Exemplo: Directo: ''María dice: "Tengo calor"'' → Indirecto: ''María dijo que tenía calor''.', '["Relatar notícias ou informações que ouvimos de outras pessoas.","Recontar conversas em uma narrativa, como em histórias ou anedotas.","Transmitir perguntas em contexto formal ou informal, como em entrevistas.","Reportar pedidos, conselhos ou sugestões, especialmente com verbos como ''pedir'', ''aconsejar'', ''sugerir''.","Expressar opiniões ou declarações de terceiros, como em artigos ou discussões."]'::jsonb, '["Esquecer de mudar o tempo verbal, mantendo o presente no discurso reportado.","Usar ''que'' desnecessariamente com perguntas indiretas (ex.: ''Preguntó que si...'' é errado; o correto é ''Preguntó si...'').","Confundir a mudança de pronomes, especialmente quando o sujeito do discurso reportado é diferente do relator.","Não ajustar advérbios de tempo e lugar, como ''hoy'' → ''ese día'', ''aquí'' → ''allí''.","Manter o imperativo no lugar do subjuntivo em pedidos no estilo indireto."]'::jsonb, '["A mudança de tempo verbal não é obrigatória se a informação ainda for verdadeira e o verbo introdutor estiver no presente, mas no passado, a transformação é padrão.","Em perguntas indiretas com ''si'', não se usa ''que''.","O imperativo direto (ex.: ''Hazlo'') vira ''que'' + subjuntivo no indireto (ex.: ''Me dijo que lo hiciera'').","As mudanças de pronomes demonstrativos também são importantes: ''esto'' vira ''eso'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4e4909674900-exercise-01', 'es', 'B2', 'Transformación de tiempos verbales', 'Quando o verbo introdutor está no pretérito (dijo), o presente do discurso direto muda para pretérito imperfeito no indireto.', 'Directo: ''Juan dice: "Estoy cansado"'' → Indirecto: ''Juan dijo que estaba cansado''.', 'Convierte al estilo indirecto: ''Pedro dice: "Quiero viajar a Brasil"''.', '["Pedro dijo que quiso viajar a Brasil.","Pedro dijo que quería viajar a Brasil.","Pedro dijo que querrá viajar a Brasil.","Pedro dijo que quiere viajar a Brasil."]'::jsonb, 1, 1, true, 'generated-grammar-es-b2-4e4909674900')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4e4909674900-exercise-02', 'es', 'B2', 'Preguntas indirectas', 'Para transformar uma pergunta direta em indireta, usamos ''si'' (para perguntas de sim/não) ou palavras interrogativas sem ''que'' e com inversão, e o verbo recua no tempo.', 'Directo: ''Ella preguntó: "¿Vienes a la fiesta?"'' → Indirecto: ''Ella preguntó si venía a la fiesta''.', 'Convierte al estilo indirecto: ''El profesor preguntó: "¿Habéis hecho los deberes?"''.', '["El profesor preguntó que si habían hecho los deberes.","El profesor preguntó si habían hecho los deberes.","El profesor preguntó si han hecho los deberes."]'::jsonb, 1, 2, true, 'generated-grammar-es-b2-4e4909674900')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4e4909674900-exercise-03', 'es', 'B2', 'Imperativos en estilo indirecto', 'Quando transmitimos um pedido ou ordem, usamos verbo introdutor + ''que'' + subjuntivo (pretérito imperfeito do subjuntivo).', 'Directo: ''Mi madre me dijo: "Limpia tu cuarto"'' → Indirecto: ''Mi madre me dijo que limpiara mi cuarto''.', 'Convierte al estilo indirecto: ''El jefe ordenó: "Terminen el informe hoy"''.', '["El jefe ordenó que terminen el informe hoy.","El jefe ordenó que terminaran el informe ese día.","El jefe ordenó que terminaron el informe ese día."]'::jsonb, 1, 3, true, 'generated-grammar-es-b2-4e4909674900')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4e4909674900-exercise-04', 'es', 'B2', 'Cambios de pronombres y expresiones de tiempo', 'Ao reportar, ajustamos pronomes pessoais/possessivos e expressões temporais para refletir a perspectiva do relator.', 'Directo: ''Ana me dijo: "Te llamo mañana"'' → Indirecto: ''Ana me dijo que me llamaría al día siguiente''.', 'Convierte al estilo indirecto: ''Mis amigos me dijeron: "Vamos a visitarte aquí"''.', '["Mis amigos me dijeron que iban a visitarme allí.","Mis amigos me dijeron que van a visitarme allí.","Mis amigos me dijeron que fueron a visitarme aquí.","Mis amigos me dijeron que irán a visitarme aquí."]'::jsonb, 0, 4, true, 'generated-grammar-es-b2-4e4909674900')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-b2-4e4909674900-exercise-05', 'es', 'B2', 'Verbos introductores y contexto', 'Escolha o verbo introdutor adequado conforme a atitude do falante (dizer, perguntar, pedir, aconselhar, etc.) e ajuste a estrutura.', 'Directo: ''Él me aconsejó: "No hagas eso"'' → Indirecto: ''Él me aconsejó que no hiciera eso''.', 'Convierte al estilo indirecto: ''Mi hermana sugirió: "Descansa un poco"''.', '["Mi hermana sugirió que descanse un poco.","Mi hermana sugirió que descansara un poco.","Mi hermana sugirió que descansó un poco.","Mi hermana sugirió que descansaría un poco."]'::jsonb, 1, 5, true, 'generated-grammar-es-b2-4e4909674900')
