insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-b2-7638b3be836f', 'es', 'B2', 'The Advanced Use of ''Se'' in Spanish (B2)', 'Neste tópico, vamos explorar os usos avançados do pronome ''se'' em espanhol, que vão além do reflexivo básico. Você aprenderá a distinguir entre o ''se'' impessoal, o ''se'' de voz passiva, o ''se'' aspectual e o ''se'' de dativo ético. Esses usos são essenciais para alcançar fluência e naturalidade em espanhol, especialmente em contextos formais e cotidianos.', '1. ''Se'' impessoal: Usa-se ''se'' + verbo na terceira pessoa do singular. Exemplo: ''Se vive bien en este país.'' (Vive-se bem neste país.)
2. ''Se'' de voz passiva: Usa-se com verbos transitivos na terceira pessoa do singular ou plural, concordando com o sujeito paciente. Exemplo: ''Se venden casas aquí.'' (Vendem-se casas aqui.)
3. ''Se'' aspectual (ou intensivo): Coloca-se antes de verbos pronominais para dar ênfase à ação ou indicar que algo foi feito completamente. Exemplo: ''Se comió toda la torta.'' (Ele comeu o bolo inteiro.)
4. ''Se'' de dativo ético: Refere-se a um participante emocionalmente envolvido na ação, mas que não é o sujeito. Exemplo: ''Mi hijo se me enfermó.'' (Meu filho ficou doente, o que me preocupou.)', '["Para expressar opiniões gerais ou fatos sem especificar quem realiza a ação: ''Se dice que va a llover.''","Para formar orações passivas sem agente: ''Se habla español en muchos países.''","Para enfatizar que uma ação foi feita por completo: ''Se leyó el libro en una noche.''","Para envolver emocionalmente o falante: ''La niña se me perdió en el mercado.''"]'::jsonb, '["Confundir o ''se'' impessoal com o reflexivo: ''Se lava'' pode ser reflexivo (ele se lava) ou impessoal (lava-se), dependendo do contexto.","Usar o ''se'' de voz passiva com verbos intransitivos: ''Se vive'' é impessoal, não passiva.","Concordância incorreta na voz passiva: ''Se vende casas'' (errado) vs. ''Se venden casas'' (correto).","Omitir o ''se'' dativo ético em situações emocionais: ''El niño se me enfermó'' (não ''El niño me enfermó'')."]'::jsonb, '["O ''se'' impessoal é muito usado em manuais, receitas e placas: ''Se prohibe fumar.''","Na voz passiva com ''se'', o verbo concorda com o sujeito gramatical: ''Se alquilan apartamentos.''","O ''se'' aspectual é comum com verbos de consumo ou realização: ''Se bebió todo el vino.''","O ''se'' dativo ético geralmente aparece com me, te, le, nos, os, les: ''Se me olvidó la cita.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

