insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-b2-86d1397ed06a', 'es', 'B2', 'El guaraní y la identidad paraguaya: un viaje por la lengua y la cultura', 'Paraguay es un país único en América del Sur. A diferencia de muchas naciones vecinas, su población mestiza es culturalmente homogénea, con una mezcla de influencias indígenas y españolas que se refleja en su idioma. El guaraní, lengua de los pueblos originarios, sobrevivió siglos de colonización y hoy es cooficial con el español. Sin embargo, su uso cotidiano ha dado lugar a un fenómeno lingüístico llamado jopará, una mezcla de guaraní y español que se habla en las calles, los hogares y los programas de televisión.', '¿Por qué se menciona que Paraguay es único en América del Sur?', '["Porque su población es completamente indígena","Porque tiene una población mestiza bastante homogénea en apariencia y cultura","Porque solo se habla español en todo el territorio","Porque no tiene influencia indígena en su cultura"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto afirma que o Paraguai é único porque sua população mestiça é bastante homogênea, tanto na aparência quanto na cultura.","options":["Porque su población es completamente indígena","Porque tiene una población mestiza bastante homogénea en apariencia y cultura","Porque solo se habla español en todo el territorio","Porque no tiene influencia indígena en su cultura"],"prompt":"¿Por qué se menciona que Paraguay es único en América del Sur?"},{"answer_index":2,"explanation_pt_br":"O jopará é a mistura de guaraní e espanhol, falada cotidianamente no Paraguai, como descrito no texto.","options":["Um idioma completamente novo, sem relação com o espanhol","Uma variante do espanhol falada apenas em zonas rurais","Uma mistura de guaraní e espanhol usada no Paraguai","Um dialeto do português falado na fronteira"],"prompt":"O que é o jopará?"},{"answer_index":3,"explanation_pt_br":"O texto menciona que, graças ao jornalista e professor, o guaraní está muito presente nas instituições educacionais do país.","options":["É completamente ignorado no sistema educacional","Está proibido por lei em instituições públicas","É ensinado apenas em universidades privadas","É ensinado graças aos esforços de pessoas como o jornalista mencionado"],"prompt":"Qual é a situação do guaraní nas escolas paraguaias?"},{"answer_index":1,"explanation_pt_br":"O texto diz que, apesar das negativas de muitas autoridades, o guaraní é promovido nas escolas.","options":["Apoiam totalmente o uso do idioma nas escolas","Mostram negativas e resistência à sua promoção","Proibiram seu uso em qualquer contexto público","Financiam a criação de um dicionário oficial"],"prompt":"Qual é a atitude de algumas autoridades paraguaias em relação ao guaraní?"},{"answer_index":2,"explanation_pt_br":"O texto afirma que o guaraní se mistura com o espanhol, gerando o jopará.","options":["É usado apenas em contextos cerimoniais e rituais","É falado corretamente pela maioria da população, sem mistura","É misturado com o espanhol, dando origem ao jopará","Era falado no passado, mas agora é uma língua morta"],"prompt":"Segundo o texto, como o guaraní é utilizado atualmente no Paraguai?"}]'::jsonb, 0, true)
