insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-41260cd53546', 'fr', 'B2', 'Registre formel, neutre et familier en français', 'Ce cours vous aidera à maîtriser les différences entre les registres formel, neutre et familier en français, afin de choisir le niveau de langue approprié dans chaque situation de communication.', 'Le registre se manifeste principalement dans le choix du vocabulaire, des constructions grammaticales et des formules de politesse. Par exemple, pour poser une question, on peut utiliser l''inversion (formel), « est-ce que » (neutre) ou l''intonation (familier). Les pronoms et les accords varient aussi : « vous » est plus formel que « tu ». De plus, certains mots et expressions sont spécifiques à un registre, comme « seoir » (formel) vs « convenir » (neutre) vs « aller bien » (familier).', '["Utiliser le registre formel dans les lettres de motivation, les courriels professionnels, les discours officiels.","Utiliser le registre neutre dans les conversations quotidiennes, les échanges avec des inconnus, les présentations.","Utiliser le registre familier entre amis, en famille, dans les contextes informels et détendus.","Respecter la politesse et la distance sociale en choisissant le registre approprié.","Adapter son langage en fonction de l''interlocuteur et de la situation."]'::jsonb, '["Utiliser le tutoiement dans un contexte formel, surtout avec une personne plus âgée ou en position d''autorité.","Employer un vocabulaire familier dans un exposé académique ou professionnel.","Confondre les formules de politesse, comme utiliser « salut » au lieu de « bonjour » dans un contexte professionnel.","Utiliser l''intonation montante pour poser une question dans un contexte formel, là où l''inversion est attendue.","Oublier d''utiliser le conditionnel pour formuler des demandes polies, comme « je voudrais » au lieu de « je veux »."]'::jsonb, '["L''utilisation du registre approprié est essentielle pour une communication efficace en français.","En français, le vouvoiement peut marquer non seulement le respect mais aussi une distance sociale.","Le registre familier est souvent utilisé dans les médias modernes et la publicité pour créer un sentiment de proximité.","Dans le langage formel, on évite les interjections et les onomatopées."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

