insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-78140de20dfa', 'fr', 'B2', 'O Registro Formal, Neutro e Familiar em Francês', 'Nesta unidade, você vai explorar as diferenças entre os registros formal, neutro e familiar em francês, com foco no uso do ''tu'' e ''vous'', na escolha lexical e em construções típicas de cada registro. Isso é essencial para se comunicar adequadamente em contextos variados, como situações profissionais, acadêmicas e cotidianas.', 'O registro refere-se ao nível de formalidade da linguagem. Em francês, as principais diferenças aparecem na escolha do pronome de tratamento (tu/vous), em certas formas verbais, e no vocabulário.

- **Registro familiar**: usa-se ''tu'', vocabulário coloquial, e algumas expressões típicas.
  - Exemplo: ''Tu vas au ciné ce soir ?'' (você vai ao cinema hoje à noite?)

- **Registro neutro**: é o registro padrão, usado em situações cotidianas sem grande formalidade, como falar com colegas ou conhecidos. Pode usar ''tu'' ou ''vous'' dependendo da relação.
  - Exemplo: ''Vous pouvez me dire l''heure, s''il vous plaît ?'' (o senhor pode me dizer as horas, por favor?)

- **Registro formal**: mais distante, usa-se ''vous'', formas de polidez, e vocabulário sofisticado.
  - Exemplo: ''Pourriez-vous me renseigner sur les horaires des trains ?'' (o senhor poderia me informar sobre os horários dos trens?)', '["No trabalho, com superiores ou clientes, use o registro formal com ''vous''.","Entre amigos próximos ou familiares, o registro familiar com ''tu'' é adequado.","Em situações neutras, como conversas com desconhecidos de mesma idade, use o neutro com ''vous''.","Escrevendo e-mails: formais para candidaturas, neutros para colegas, familiares para amigos.","Em pequenas conversas, o registro familiar usa expressões como ''sympa'' em vez de ''gentil''.","Em discursos ou apresentações, predomina o registro formal."]'::jsonb, '["Usar ''tu'' com pessoas mais velhas ou em chefia: pode parecer desrespeitoso.","Usar ''vous'' com amigos: cria distanciamento desnecessário.","Misturar registros, por exemplo, usar ''tu'' e depois ''vous'' no mesmo discurso sem intenção.","Empregar gírias em contexto formal (ex.: ''le taf'' em vez de ''le travail'')."]'::jsonb, '["O ''vous'' pode ser usado como forma de plural ou de polidez, com verbos conjugados correspondentes.","Na dúvida, prefira o registro formal; é mais seguro.","O registro pode variar por região (Canadá, Bélgica, Suíça), mas as regras gerais são as mesmas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

