insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-871ee03e56e3', 'fr', 'B2', 'Nominalisation (B2)', 'A nominalização é o processo de transformar verbos ou adjetivos em substantivos. Em francês, isso é muito comum e permite expressar ideias de forma mais concisa e formal. Nesta lição, você vai aprender os principais sufixos usados para formar substantivos a partir de verbos e adjetivos, e como usá-los em contextos do dia a dia.', 'Para formar substantivos a partir de verbos, use os sufixos: -tion/-sion (ex.: informer → information, décider → décision), -ment (ex.: développer → développement), -age (ex.: bricoler → bricolage), -ure (ex.: ouvrir → ouverture). Para formar substantivos a partir de adjetivos, use: -ité (ex.: rapide → rapidité), -esse (ex.: triste → tristesse), -eur (ex.: grand → grandeur). Nem sempre a formação é regular; às vezes, o radical muda (ex.: choisir → choix, savoir → savoir-faire).', '["Usada em contextos formais e acadêmicos para dar mais clareza e precisão.","Permite resumir ideias complexas em um único substantivo.","Muito frequente em textos jornalísticos e científicos.","Evita repetição de verbos nas frases."]'::jsonb, '["Confundir sufixos -tion e -sion (ex.: *discution → discussion).","Usar o sufixo errado para o verbo (ex.: *développation → développement).","Esquecer de adaptar o radical do verbo antes do sufixo.","Usar nominalização em contexto informal, onde o verbo é mais natural."]'::jsonb, '["Atenção ao gênero: substantivos terminados em -tion, -sion, -ité, -esse são femininos; -ment é masculino.","Alguns verbos têm dois substantivos com sentidos diferentes (ex.: constatation vs constat).","Na linguagem falada, é comum usar a forma verbal; na escrita formal, prefira a nominalização."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

