insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-33462952c00b', 'fr', 'B2', 'La mise en relief', 'A mise en relief é uma estrutura usada para destacar um elemento da frase, dando-lhe ênfase. Em francês, isso é feito principalmente com as expressões ''c''est... qui'' e ''c''est... que'', seguindo padrões específicos.', 'Para destacar o sujeito: C''est + [sujeito] + qui + [verbo]. Exemplo: C''est Marie qui a gagné. Para destacar outro elemento (objeto, complemento, etc.): C''est + [elemento] + que + [resto da frase]. Exemplo: C''est ce livre que je veux. No passado, usa-se ''c''était'' no lugar de ''c''est''. Também é possível usar ''ce sont'' para plural, embora ''c''est'' seja aceito em registro informal.', '["Destacar o sujeito da ação, como em ''C''est moi qui ai fait cela''.","Destacar um objeto direto, como em ''C''est ce film que j''ai vu hier''.","Destacar um complemento de lugar, como em ''C''est à Paris que je vais''.","Destacar um complemento de tempo, como em ''C''est demain que nous partons''."]'::jsonb, '["Usar ''qui'' em vez de ''que'' quando o elemento destacado não é o sujeito.","Esquecer de fazer a concordância do verbo com o sujeito quando ele é destacado.","Usar ''c''est'' com plural em contexto formal; prefira ''ce sont''."]'::jsonb, '["Em francês falado, ''c''est'' é frequentemente usado mesmo no plural, mas em escrita formal, usa-se ''ce sont''.","A estrutura é comum em perguntas: ''C''est toi qui as dit ça ?''","Para enfatizar um advérbio, usa-se ''c''est... que'', como em ''C''est ici que j''habite''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

