insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-6a202449e7df', 'fr', 'B2', 'Le subjonctif étendu : après les conjonctions et dans les relatives', 'Neste tópico, você vai expandir seu uso do subjuntivo em francês além dos casos básicos (expressões de vontade, emoção, etc.), focando em conjunções que exigem subjuntivo e em orações relativas com valor de hipótese ou necessidade. O domínio dessas estruturas é essencial para alcançar um nível B2, permitindo que você expresse ideias mais complexas e sutis.', 'O subjuntivo presente é formado a partir do radical da 3ª pessoa do plural do presente do indicativo, adicionando as terminações: -e, -es, -e, -ions, -iez, -ent. Exceções comuns incluem os verbos être (sois, sois, soit, soyons, soyez, soient) e avoir (aie, aies, ait, ayons, ayez, aient). Para as conjunções, a estrutura é: conjunção + sujeito + verbo no subjuntivo. Nas relativas com subjuntivo, utiliza-se geralmente um antecedente indefinido ou negativo, como ''quelque chose'', ''personne'', ''rien'', ou expressões como ''le seul'', ''le premier'', seguidas de verbo no subjuntivo.', '["Após conjunções de tempo, como ''avant que'', '' jusqu''à ce que'', ''en attendant que''.","Após conjunções de concessão, como ''bien que'', ''quoique'', ''sans que''.","Após conjunções de condição ou finalidade, como ''à condition que'', ''pourvu que'', ''afin que''.","Em orações relativas que expressam uma hipótese, um desejo ou uma necessidade, especialmente após antecedentes negativos, indefinidos ou superlativos."]'::jsonb, '["Usar o indicativo após ''bien que'' e ''quoique''.","Confundir ''avant que'' (subjuntivo) com ''après que'' (indicativo).","Omitir o subjuntivo em relativas após ''le seul'' ou ''le premier'', especialmente quando a existência do antecedente é incerta."]'::jsonb, '["Em registos formais, ''avant que'' é seguido de ''ne'' explétif: ''avant qu''il ne parte''.","A conjunção ''pour que'' é usada para finalidade e exige subjuntivo.","Nas relativas, o subjuntivo é frequentemente usado para indicar que o resultado é esperado ou desejado, e não real."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

