insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-7c060d33a54d', 'fr', 'B2', 'Les conditionnels irréels (si + plus-que-parfait + conditionnel passé)', 'Nesta lição, você vai aprender a usar as estruturas condicionais irreais em francês, que expressam situações hipotéticas no passado, ou seja, fatos que não aconteceram e cujas consequências seriam diferentes. Esse é um tópico essencial para alcançar o nível B2, pois permite falar sobre arrependimentos, críticas e situações imaginárias de forma precisa e sofisticada.', 'A estrutura é composta por duas partes: a condição (introduzida por ''si'') e o resultado. Para o irreal do passado, usa-se ''si + mais-que-perfeito do indicativo'' na condição, e o ''condicional passado'' no resultado. O condicional passado é formado com o condicional presente do verbo auxiliar (avoir ou être) + particípio passado. Exemplo: ''Si j''avais su, je serais venu.'' (Se eu tivesse sabido, eu teria vindo). Na linguagem informal, pode-se usar o condicional presente no resultado, mas o condicional passado é mais correto e enfatiza a ideia de passado.', '["Para expressar arrependimento sobre ações passadas: ''Si j''avais étudié, j''aurais réussi l''examen.''","Para criticar ou apontar erros do passado: ''Si tu avais écouté, tu n''aurais pas fait cette erreur.''","Para imaginar cenários alternativos na história: ''Si Napoléon avait gagné, l''Europe serait différente.''","Para fazer suposições sobre o passado sem certeza: ''Si elle avait fini plus tôt, elle serait là maintenant.''"]'::jsonb, '["Usar o condicional presente na cláusula com ''si'': ''Si j''aurais su'' é incorreto; o correto é ''Si j''avais su''.","Confundir a ordem das palavras na negação: ''Je ne serais pas venu'' (não ''Je serais ne pas venu'').","Esquecer a concordância do particípio passado com ''être'': ''elle serait venue'' (não ''venu'').","Usar o presente do indicativo após ''si'' quando a situação é passada: ''Si j''ai su'' em vez de ''Si j''avais su''.","Usar o condicional na cláusula ''si'' em frases hipotéticas passadas."]'::jsonb, '["Em francês, a cláusula com ''si'' nunca leva condicional, apenas indicativo ou subjuntivo (embora o subjuntivo não seja usado aqui).","Quando a condição é no passado e o resultado é no presente, pode-se usar o condicional presente no resultado: ''Si j''avais pris le train, je serais chez moi maintenant''.","A inversão do sujeito na cláusula com ''si'' é possível na linguagem formal: ''Si j''avais su'' → ''Si avais-je su'' (raro e literário).","A estrutura também pode ser usada para conselhos: ''Si j''étais toi, j''aurais accepté'' (mas para conselhos, normalmente usa-se o presente do indicativo + condicional presente).","As contrações com ''que'' são comuns: ''Si j''avais su qu''il était là...''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

