insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-b2-7a9fad4615c4', 'fr', 'B2', 'Les pronoms relatifs composés', 'Nesta lição, você vai aprender a usar os pronomes relativos compostos em francês: lequel, auquel, duquel e suas variações. Esses pronomes são essenciais para conectar ideias e para tornar seu discurso mais preciso e sofisticado, especialmente após preposições.', 'Os pronomes relativos compostos são formados pelo artigo definido (le, la, les) + ''quel'', ou pelas preposições ''à'' ou ''de'' contraídas com essas formas: à + lequel = auquel, à + laquelle = à laquelle, à + lesquels = auxquels, à + lesquelles = auxquelles; de + lequel = duquel, de + laquelle = de laquelle, de + lesquels = desquels, de + lesquelles = desquelles. Eles concordam em gênero e número com o antecedente.', '["Use os pronomes relativos compostos depois de preposições como ''à'', ''de'', ''avec'', ''sans'', ''pour'', ''par'', etc., para substituir um substantivo já mencionado.","Use ''auquel'', ''à laquelle'', etc., quando o verbo é seguido de ''à'' (ex.: penser à, songer à, réussir à).","Use ''duquel'', ''de laquelle'', etc., quando o verbo é seguido de ''de'' (ex.: parler de, avoir besoin de, se souvenir de).","Use ''sur lequel'', ''sous lequel'', etc., para indicar posição ou lugar.","Use os relativos compostos para evitar repetições e tornar frases mais elegantes."]'::jsonb, '["Confundir ''dont'' com ''duquel''. ''Dont'' é usado quando o verbo é seguido de ''de'', mas sem preposição extra; ''duquel'' é usado depois de preposições como ''près de'', ''à côté de'', ''loin de''.","Esquecer a concordância: com antecedente feminino plural, usar ''auxquelles'' ou ''desquelles'', nunca ''auxquels''.","Usar ''dont'' em vez de ''duquel'' após preposições complexas como ''à cause de''.","Omitir o artigo quando necessário: dizer ''le livre de lequel'' em vez de ''le livre duquel''."]'::jsonb, '["Os pronomes relativos compostos são invariáveis em forma, mas variam em gênero e número.","Em francês formal, depois de preposições diferentes de ''à'' e ''de'', usa-se ''lequel'' e suas formas (ex.: avec lequel, pour lequel).","A forma ''dont'' substitui ''de + lequel'' apenas quando não há outra preposição; cuidado com a diferença. Ex.: ''C''est le livre dont je t''ai parlé'' (parler de) vs. ''C''est le livre à côté duquel je me suis assis'' (à côté de)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

