insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b2-d755c05cd134', 'fr', 'B2', 'Le subjonctif élargi : maîtriser l''expression du doute et de l''émotion', 'Au niveau B2, le subjonctif ne se limite plus aux expressions impersonnelles classiques. Vous savez déjà utiliser « il faut que » ou « je pense que » (avec l''indicatif), mais le subjonctif s''étend à des contextes plus nuancés. Il exprime une subjectivité, un jugement, une émotion, ou une hypothèse. Par exemple, après des verbes comme « douter », « craindre », « souhaiter » ou des locutions comme « bien que », « pourvu que », « à condition que ». 

Prenons un exemple concret : « Je doute qu''il vienne ce soir. » Ici, le doute est exprimé par le subjonctif. En revanche, « Je suis sûr qu''il viendra » utilise l''indicatif car il n''y a pas de doute. Cette distinction est cruciale pour nuancer votre français. 

De plus, le subjonctif apparaît dans des propositions relatives qui expriment une recherche d''un objet ou d''une personne indéfinis. Par exemple : « Je cherche un livre qui soit intéressant. » L''indicatif exprimerait une certitude, le subjonctif une possibilité. 

Enfin, après certaines conjonctions de temps, comme « avant que » et « jusqu''à ce que », le subjonctif est obligatoire. « Attends qu''il arrive » est incorrect ; on dit « Attends qu''il arrive », mais le verbe est au subjonctif (arrive). Il faut donc être attentif à ces subtilités. 

Cette leçon vous permettra de passer d''un usage basique à une maîtrise plus fine du subjonctif, ce qui est un signe de fluidité et de sophistication. Vous allez explorer cinq exercices qui couvrent ces usages étendus, avec des explications en portugais pour vous aider. Prêt à relever le défi ?', 'Quel verbe introduit obligatoirement le subjonctif à la forme affirmative ?', '["croire","douter","penser","espérer"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O verbo ''douter'' (duvidar) à forma afirmativa exige o subjuntivo: ''Je doute qu''il vienne.'' Os verbos ''croire'', ''penser'' e ''espérer'' à forma afirmativa geralmente usam o indicativo, a menos que estejam na negativa ou interrogativa.","options":["croire","douter","penser","espérer"],"prompt":"Quel verbe introduit obligatoirement le subjonctif à la forme affirmative ?"},{"answer_index":1,"explanation_pt_br":"''Bien que'' (embora) é seguida de subjuntivo: ''Bien qu''il soit en retard...'' ''Parce que'', ''après que'' e ''pendant que'' são seguidas de indicativo.","options":["parce que","bien que","après que","pendant que"],"prompt":"Quelle conjonction est suivie du subjonctif ?"},{"answer_index":1,"explanation_pt_br":"Após ''il faut que'', o verbo deve estar no subjuntivo presente: ''sois'' do verbo ''être''. A forma ''es'' é do indicativo, ''seras'' é futuro do indicativo. A opção 3 tem um erro de conjugação, a 4 repete a correta.","options":["Il faut que tu es prudent.","Il faut que tu sois prudent.","Il faut que tu seras prudent."],"prompt":"Choisissez la phrase correcte :"},{"answer_index":1,"explanation_pt_br":"Após expressões de emoção como ''être content que'', usa-se o subjuntivo: ''Je suis content qu''il vienne.'' As outras opções usam o indicativo ou o condicional, que não são adequados aqui.","options":["Je suis content qu''il vient.","Je suis content qu''il vienne.","Je suis content qu''il viendra.","Je suis content qu''il viendrait."],"prompt":"Dans quelle phrase le subjonctif est-il utilisé à cause d''une émotion ?"},{"answer_index":0,"explanation_pt_br":"A conjunção ''pourvu que'' (desde que, contanto que) exige o subjuntivo. ''Fasse'' é subjuntivo presente de ''faire''. As outras opções usam o futuro do indicativo ou o passado composto.","options":["Pourvu qu''il fasse beau demain.","Pourvu qu''il fera beau demain.","Pourvu qu''il a fait beau demain."],"prompt":"Quelle phrase exprime une hypothèse avec le subjonctif ?"}]'::jsonb, 0, true)
