insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-b2-cd692e740aa9', 'fr', 'B2', 'Les conditionnels irréels : et si tout était possible ?', 'Dans la vie, nous aimons imaginer des scénarios alternatifs. Que ferions-nous si nous gagnions au loto ? Où irions-nous si nous avions plus de temps ? Ces questions, bien que fictives, nous permettent de réfléchir à nos priorités et à nos désirs. En français, pour exprimer ces situations imaginaires, nous utilisons les conditionnels irréels, notamment le conditionnel passé. Ce temps est essentiel pour parler de ce qui aurait pu se passer, mais ne s''est pas produit, ou pour exprimer des regrets et des souhaits. Dans cette leçon, nous allons explorer comment former et utiliser ces structures, avec des exemples concrets et des exercices pratiques. Préparez-vous à voyager dans le monde du « si » et du « aurait » !', 'Quel est le but principal du conditionnel passé en français ?', '["Exprimer une action future certaine","Parler d''une action qui aurait pu se produire dans le passé","Décrire une action habituelle dans le passé","Donner un ordre poli"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Le conditionnel passé est utilisé pour parler d''une action qui n''a pas eu lieu mais qui aurait pu se produire, souvent exprimant un regret ou un souhait.","options":["Exprimer une action future certaine","Parler d''une action qui aurait pu se produire dans le passé","Décrire une action habituelle dans le passé","Donner un ordre poli"],"prompt":"Quel est le but principal du conditionnel passé en français ?"},{"answer_index":0,"explanation_pt_br":"Le conditionnel passé se forme avec l''auxiliaire avoir ou être conjugué au conditionnel présent, suivi du participe passé du verbe principal.","options":["Auxiliaire (avoir ou être) au conditionnel présent + participe passé","Auxiliaire (avoir ou être) à l''imparfait + infinitif","Verbe au conditionnel présent + infinitif","Auxiliaire (avoir ou être) au futur simple + participe passé"],"prompt":"Comment forme-t-on le conditionnel passé ?"},{"answer_index":0,"explanation_pt_br":"La phrase correcte est ''Si j''avais su, je serais venu plus tôt.'' car elle utilise le plus-que-parfait dans la condition et le conditionnel passé dans la conséquence, exprimant une action non réalisée dans le passé.","options":["Si j''avais su, je serais venu plus tôt.","Si je savais, je viendrais plus tôt.","Si je sais, je viendrai plus tôt.","Si je savais, je serais venu plus tôt."],"prompt":"Quelle phrase est au conditionnel passé ?"},{"answer_index":0,"explanation_pt_br":"Cette structure exprime une hypothèse sur le passé, c''est-à-dire une situation imaginaire contraire à ce qui s''est réellement passé.","options":["Exprimer une hypothèse sur le passé","Exprimer une hypothèse sur le présent","Exprimer une certitude sur le futur","Exprimer une action habituelle au passé"],"prompt":"Quelle est la fonction principale de la structure « si + plus-que-parfait, conditionnel passé » ?"},{"answer_index":0,"explanation_pt_br":"La phrase correcte est ''Elle aurait aimé voyager plus jeune.'' car elle exprime un regret concernant le passé, en utilisant le conditionnel passé.","options":["Elle aurait aimé voyager plus jeune.","Elle aimerait voyager plus jeune.","Elle aimait voyager plus jeune.","Elle aimera voyager plus jeune."],"prompt":"Choisissez la phrase correcte avec le conditionnel passé."}]'::jsonb, 0, true)
