insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-de509a0d9305', 'it', 'B2', 'Discorso Indiretto al Passato: Riportare le Parole degli Altri', 'In questa lezione, imparerai come riportare in italiano ciò che qualcuno ha detto in passato, usando il discorso indiretto. Questa abilità è essenziale per raccontare conversazioni, interviste o dichiarazioni in modo accurato e naturale. Esploreremo le trasformazioni necessarie nei tempi verbali, nei pronomi e nelle espressioni di tempo e luogo.', 'Per formare il discorso indiretto al passato, di solito si usa il verbo introduttivo al passato (es. ''ha detto'', ''ha chiesto'') seguito da ''che'' per le affermazioni, ''se'' per le domande sì/no, o dalla parola interrogativa (es. ''dove'', ''quando'') per le domande aperte. Il verbo della frase originale subisce una trasformazione: il presente indicativo diventa imperfetto, il passato prossimo diventa trapassato prossimo, il futuro diventa condizionale composto, e l''imperativo diventa congiuntivo imperfetto. Inoltre, pronomi, possessivi e espressioni di tempo e luogo cambiano per adattarsi alla prospettiva di chi riporta.', '["Riportare dichiarazioni o affermazioni fatte in passato (es. ''Maria ha detto che era stanca.'').","Riportare domande poste in passato (es. ''Mi ha chiesto se avevo fame.'').","Riportare ordini o richieste (es. ''Il professore ha detto di studiare di più.'').","Riportare notizie o informazioni apprese in precedenza (es. ''Hanno annunciato che il concerto era stato cancellato.'').","Riportare discorsi indiretti in narrazioni o resoconti."]'::jsonb, '["Non cambiare il tempo verbale: ''Ha detto che è stanco'' invece di ''Ha detto che era stanco''.","Dimenticare di cambiare i pronomi: ''Ha detto che io sono stanco'' invece di ''Ha detto che lui era stanco'' (se riferito a un''altra persona).","Usare il modo sbagliato per le domande: ''Mi ha chiesto che dove andavo'' invece di ''Mi ha chiesto dove andavo''.","Non adattare le espressioni di tempo: ''Ha detto che oggi era occupato'' invece di ''Ha detto che quel giorno era occupato''.","Confondere il congiuntivo con l''indicativo dopo ''che'' in frasi come ''Speravo che venisse'' (non ''veniva'')."]'::jsonb, '["Quando il verbo introduttivo è al presente (es. ''dice''), il tempo verbale resta invariato.","Per le domande indirette, non si usa il punto interrogativo.","Nell''italiano parlato informale, a volte si mantiene il tempo originale, ma a livello B2 è importante usare le forme corrette.","La concordanza dei tempi può variare se l''azione riportata è ancora vera o futura al momento del discorso."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-de509a0d9305-exercise-01', 'it', 'B2', 'Trasformare una frase al presente', 'Trasforma la frase dal discorso diretto all''indiretto, cambiando il tempo verbale e gli altri elementi necessari.', 'Diretto: ''Sono stanco.'' Indiretto: Ha detto che era stanco.', 'Come si trasforma: ''Mario dice: "Ho fame"'' in discorso indiretto al passato?', '["Mario ha detto che ha fame.","Mario ha detto che aveva fame.","Mario ha detto che ebbe fame.","Mario ha detto che avesse fame."]'::jsonb, 1, 1, true, 'generated-grammar-it-b2-de509a0d9305')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-de509a0d9305-exercise-02', 'it', 'B2', 'Cambiare i pronomi', 'Nel discorso indiretto, i pronomi devono essere adattati alla prospettiva di chi riporta.', 'Diretto: ''Io ti amo.'' Indiretto: Ha detto che mi amava.', 'Quale frase è corretta? (Paolo a Giulia: ''Ti chiamerò'')', '["Paolo ha detto che la chiamerà.","Paolo ha detto che le avrebbe chiamato.","Paolo ha detto che le avrebbe chiamata.","Paolo ha detto che la chiamava."]'::jsonb, 2, 2, true, 'generated-grammar-it-b2-de509a0d9305')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-de509a0d9305-exercise-03', 'it', 'B2', 'Trasformare una domanda', 'Per trasformare una domanda, usa ''se'' per sì/no e la parola interrogativa per le altre.', 'Diretto: ''Dove vai?'' Indiretto: Mi ha chiesto dove andavo.', 'Come si trasforma: ''Lei ha chiesto: "Quando arrivi?"''', '["Lei ha chiesto quando arrivo.","Lei ha chiesto quando arrivavo.","Lei ha chiesto se quando arrivavo.","Lei ha chiesto quando sarei arrivato."]'::jsonb, 1, 3, true, 'generated-grammar-it-b2-de509a0d9305')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-de509a0d9305-exercise-04', 'it', 'B2', 'Riportare un ordine', 'Gli ordini nel discorso indiretto si esprimono con ''di'' + infinito.', 'Diretto: ''Studia!'' Indiretto: Mi ha detto di studiare.', 'Come si trasforma: ''Il dottore dice: "Prenda questo medicinale"''?', '["Il dottore ha detto di prendere questo medicinale.","Il dottore ha detto che prendesse questo medicinale.","Il dottore ha detto di prendere quel medicinale.","Il dottore ha detto che prenda quel medicinale."]'::jsonb, 2, 4, true, 'generated-grammar-it-b2-de509a0d9305')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-de509a0d9305-exercise-05', 'it', 'B2', 'Adattare il tempo e le espressioni', 'Quando il verbo introduttivo è al passato, il tempo della frase riportata spesso arretra di un grado.', 'Diretto: ''Ieri ho mangiato pizza.'' Indiretto: Ha detto che il giorno prima aveva mangiato pizza.', 'Completa: ''Luca ha detto che ___ (andare) al cinema il giorno prima.''', '["è andato","era andato","andava","fosse andato"]'::jsonb, 1, 5, true, 'generated-grammar-it-b2-de509a0d9305')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-ec9c25842a43', 'it', 'B2', 'La voce passiva e il fare causativo', 'Nesta lição, você vai aprender a usar a voz passiva e a construção causativa com ''fare'' em italiano. A voz passiva é usada para enfatizar a ação em vez de quem a realiza, enquanto o causativo ''fare'' expressa que você faz com que algo seja feito por outros. Essas estruturas são comuns em contextos formais e informais e ajudam a tornar sua comunicação mais natural e precisa.', 'Para formar a voz passiva, use o verbo ''essere'' no tempo desejado seguido do particípio passado do verbo principal. O particípio concorda em gênero e número com o sujeito. Por exemplo: ''La pizza è fatta da Mario.'' (A pizza é feita pelo Mario). Na construção causativa, use ''fare'' + infinitivo do verbo principal, e o agente pode ser introduzido por ''a'' ou ''da''. Por exemplo: ''Faccio riparare la macchina dal meccanico.'' (Faço o carro ser consertado pelo mecânico). Em tempos compostos, o particípio passado de ''fare'' pode ser invariável ou concordar com o objeto direto.', '["Voz passiva: para focar na ação ou no objeto em vez do agente.","Voz passiva com ''si'' impessoal: para expressar ações gerais ou impessoais (ex.: ''Qui si parla italiano.'').","Causativo ''fare'': para indicar que você organiza ou solicita que algo seja feito por outra pessoa.","Causativo ''fare'' com partes do corpo: para indicar que você faz algo pelo próprio corpo (ex.: ''Mi sono fatto tagliare i capelli.'')."]'::jsonb, '["Confundir ''essere'' e ''venire'' na voz passiva: ''venire'' é usado só em tempos simples.","Esquecer a concordância do particípio passado na voz passiva.","Usar ''fare'' + infinitivo sem o objeto direto correto, alterando o sentido.","Na forma reflexiva do causativo, não usar o pronome reflexivo apropriado."]'::jsonb, '["A voz passiva pode ser formada com ''venire'' em tempos simples (ex.: ''La porta viene aperta alle 8.'').","No causativo, o agente pode ser precedido por ''a'' (se for uma pessoa) ou ''da'' (se for uma entidade ou instrumento).","A forma negativa do causativo: ''Non faccio riparare la macchina.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

