insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-9ebe3099326f', 'it', 'B2', 'Expanded Relative Clauses', 'As relative clauses expandidas permitem adicionar informações detalhadas sobre um substantivo sem iniciar uma nova frase. Neste nível B2, você aprenderá a usar pronomes relativos como ''il quale'', ''la quale'', ''cui'', e formas com preposições para criar frases mais complexas e naturais em italiano.', 'Para formar relative clauses expandidas, use pronomes relativos após o antecedente. ''Il quale/la quale'' concordam em gênero e número com o substantivo. ''Cui'' é invariável e frequentemente usado com preposições (es. ''con cui'', ''di cui'', ''per cui''). Exemplos: ''Il libro, il quale ho comprato ieri, è interessante.'' / ''La persona con cui lavoro è simpatica.'' / ''Il motivo per cui sono qui è importante.''', '["Para acrescentar informações não essenciais entre vírgulas: ''Mio fratello, il quale vive a Roma, viene a trovarmi.''","Para expressar posse ou relação: ''La casa di cui ti ho parlato è in vendita.''","Para indicar causa, tempo ou modo com preposições: ''Il giorno in cui ci siamo conosciuti era soleggiato.''","Para evitar repetição em textos formais ou escritos: ''I candidati, i quali hanno superato l''esame, riceveranno un certificato.''","Para fazer referência a uma frase inteira: ''Ha piovuto tutto il giorno, il che ha rovinato i nostri piani.''"]'::jsonb, '["Confundir ''che'' com ''cui'' quando a preposição é necessária: ''La città che vengo'' (errado) vs. ''La città da cui vengo'' (correto).","Errar a concordância de ''il quale'' com o substantivo: ''Le ragazze, il quale sono arrivate...'' (errado) vs. ''le quali'' (correto).","Usar ''il quale'' em vez de ''cui'' em contextos informais, causando formalidade excessiva.","Omitir a preposição antes de ''cui'': ''La persona cui ho parlato'' (errado sem preposição? Na verdade, ''cui'' pode ser usado sem preposição se o verbo exige, mas aqui o correto é ''a cui ho parlato'' ou ''con cui ho parlato'' dependendo do verbo).","Colocar vírgulas incorretamente em relative clauses restritivas (sem vírgulas) versus não restritivas (com vírgulas)."]'::jsonb, '["Em italiano, ''che'' é usado para sujeito e objeto direto, e é invariável.","''Cui'' é usado para complementos indiretos e sempre precedido por preposição (inclusive quando a preposição é ''di'' para posse).","''Il quale'' é mais formal e usado principalmente na escrita ou em discursos cuidados.","A forma ''il che'' refere-se a toda a oração anterior e é invariável.","Em relative clauses não restritivas, as vírgulas são obrigatórias."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

