insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-2b652f5afa1c', 'it', 'B2', 'Il Congiuntivo Passato e Imperfetto', 'Nesta unidade, você vai aprender a usar o congiuntivo passato e o congiuntivo imperfetto em italiano. O congiuntivo é um modo verbal usado para expressar dúvida, incerteza, desejo, opinião pessoal ou situações irreais. Enquanto o congiuntivo imperfetto se refere a ações no passado que não são factualmente confirmadas, o congiuntivo passato indica uma ação que ocorreu antes de outra no passado. Vamos explorar sua formação e seus usos principais, com exemplos práticos para o nível B2.', '**Congiuntivo Imperfetto**: Para formar o congiuntivo imperfetto, pegue a raiz do verbo no infinitivo (para verbos regulares) e adicione as terminações: -assi, -assi, -asse, -assimo, -aste, -assero para a 1ª conjugação (-are); -essi, -essi, -esse, -essimo, -este, -essero para a 2ª conjugação (-ere); -issi, -issi, -isse, -issimo, -iste, -issero para a 3ª conjugação (-ire). Exemplos: parlare -> parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; credere -> credessi, credessi, credesse, credessimo, credeste, credessero; partire -> partissi, partissi, partisse, partissimo, partiste, partissero. Verbos irregulares comuns: essere -> fossi, fossi, fosse, fossimo, foste, fossero; avere -> avessi, avessi, avesse, avessimo, aveste, avessero; fare -> facessi, facessi, facesse, facessimo, faceste, facessero.', '["Uso do congiuntivo imperfetto em orações subordinadas introduzidas por ''se'' para expressar condições irreais ou hipotéticas no presente ou futuro (ex.: ''Se avessi tempo, viaggerei.'')","Uso do congiuntivo imperfetto após expressões impessoais no passado, como ''era necessario che'', ''era meglio che'', ''non era giusto che''.","Uso do congiuntivo imperfetto para expressar desejo, dúvida ou opinião no passado, com verbos como ''volere'', ''desiderare'', ''credere'', ''pensare'' (ex.: ''Speravo che venissi.'')","Uso do congiuntivo passato para indicar uma ação que ocorreu antes de outra no passado, geralmente introduzido por ''benché'', ''sebbene'', ''nonostante'', ''prima che'', ''dopo che'' (ex.: ''Benché avesse studiato, non passò l''esame.'')","Uso do congiuntivo passato em orações relativas que expressam uma ação anterior a um tempo passado (ex.: ''Cercavo un libro che avesse vinto il premio.'')","Uso do congiuntivo passato após expressões de sentimento ou julgamento no passado (ex.: ''Era strano che avesse detto una cosa simile.'')"]'::jsonb, '["Confundir o uso do congiuntivo imperfetto com o passato prossimo do indicativo (ex.: ''Speravo che vieni'' em vez de ''Speravo che venissi'').","Usar o congiuntivo imperfetto em vez do condizionale passato em orações condicionais irreais do passado (ex.: ''Se avevo saputo, sarei venuto'' em vez de ''Se avessi saputo, sarei venuto'').","Esquecer de concordar o verbo no congiuntivo com o sujeito da subordinada (ex.: ''Speravo che tu venisse'' em vez de ''Speravo che tu venissi'').","Aplicar a forma do congiuntivo imperfetto a verbos irregulares como se fossem regulares (ex.: ''fasse'' em vez de ''facesse'')."]'::jsonb, '["Em italiano moderno, especialmente na língua falada, o congiuntivo é frequentemente substituído pelo indicativo, mas o uso correto ainda é exigido em contextos formais e na escrita.","A escolha entre congiuntivo imperfetto e passato depende da relação temporal entre a oração principal e a subordinada: se a ação da subordinada é simultânea ou posterior à principal, usa-se imperfetto; se é anterior, usa-se passato.","Alguns verbos que frequentemente requerem congiuntivo incluem: ''volere'', ''desiderare'', ''sperare'', ''credere'', ''pensare'', ''temere'', ''dubitare'', e expressões impessoais como ''è possibile'', ''è giusto'', ''è meglio'', ''non è vero''."]'::jsonb, 0, true)
