insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-1734a16596d2', 'it', 'B2', 'Sequenza Temporale: Passato Prossimo, Imperfetto e Trapassato Prossimo', 'Nesta unidade, você vai aprender a usar corretamente os tempos passados do italiano para narrar eventos e descrever situações no passado. Vamos focar na diferença entre o passato prossimo (para ações concluídas), o imperfetto (para ações habituais ou descrições) e o trapassato prossimo (para ações anteriores a outras ações passadas). Você verá como combinar esses tempos para criar narrativas claras e precisas.', 'O passato prossimo é formado com o presente de ''avere'' ou ''essere'' + o particípio passado do verbo (ex.: ho mangiato, sono andato/a). O imperfetto é formado com as terminações -avo, -avi, -ava, -avamo, -avate, -avano para a primeira conjugação, e -evo, -evi, -eva, -evamo, -evate, -evano para a segunda e terceira (ex.: parlavo, vedevo, dormivo). O trapassato prossimo é formado com o imperfetto de ''avere'' ou ''essere'' + o particípio passado (ex.: avevo mangiato, ero andato/a).', '["Usamos o passato prossimo para ações concluídas em um tempo definido (ex.: Ieri ho comprato il giornale).","Usamos o imperfetto para ações habituais no passado (ex.: Da bambino giocavo sempre nel parco).","Usamos o imperfetto para descrições de pessoas, lugares e situações no passado (ex.: La città era tranquilla).","Usamos o trapassato prossimo para expressar uma ação anterior a outra no passado (ex.: Quando sono arrivato, avevano già mangiato).","Para ações simultâneas, usamos o imperfetto em ambas (ex.: Mentre leggevo, ascoltavo la musica).","Para ações sequenciais, usamos o passato prossimo (ex.: Mi sono alzato, ho fatto colazione e sono uscito)."]'::jsonb, '["Confundir passato prossimo e imperfetto para ações habituais: para hábitos, use sempre o imperfetto, não o passato prossimo.","Usar o trapassato prossimo sem uma ação posterior clara: ele só é usado quando há uma referência a outra ação passada.","Esquecer o uso do auxiliar ''essere'' com verbos de movimento e de mudança de estado, concordando o particípio com o sujeito (ex.: Lei è andata).","Usar o imperfetto para ações concluídas em um momento específico: para isso, use o passato prossimo (ex.: Ieri ho visto un film).","Formar o trapassato prossimo com o presente de avere/essere em vez do imperfetto (ex.: *ho avuto mangiato é incorreto; o certo é avevo mangiato)."]'::jsonb, '["Na narração, o imperfetto define o cenário, enquanto o passato prossimo avança a história. O trapassato prossimo é usado para ações que ocorreram antes do início da narração.","Com ''mentre'' (enquanto), geralmente usamos o imperfetto: Mentre pioveva, io leggevo.","Os tempos compostos com ''essere'' exigem concordância do particípio com o sujeito: loro sono partiti, noi siamo uscite (se todas mulheres).","Alguns verbos mudam de auxiliar dependendo do uso (ex.: ''salire'' com ''essere'' quando intransitivo, com ''avere'' quando transitivo).","Em diálogos, o imperfetto pode ser usado para cortesia: Volevo chiederle una cosa (mais polido que ''voglio'').","Expressões de tempo frequente como ''spesso'', ''di solito'' exigem o imperfetto para hábitos passados.","O trapassato prossimo é frequentemente usado com expressões como ''già'', ''ancora'', ''prima''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

