insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-c55dc8317879', 'it', 'B2', 'Unreal Conditionals in Italian', 'Nesta lição, você vai aprender a usar as condicionais irreais em italiano, que expressam situações hipotéticas, contrárias aos fatos ou imaginárias. Essas estruturas são essenciais para falar de desejos, conselhos e situações que não aconteceram ou que são improváveis.', 'As condicionais irreais em italiano usam o congiuntivo imperfetto na oração subordinada (se) e o condizionale semplice na oração principal. Exemplo: Se avessi tempo, viaggerei di più. (Se eu tivesse tempo, viajaria mais.)', '["Situações hipotéticas no presente: Se avessi soldi, comprerei una macchina nuova.","Desejos irreais: Magari avessi più tempo!","Conselhos: Se fossi in te, accetterei quel lavoro.","Eventos improváveis: Se vincessi alla lotteria, smetterei di lavorare.","Cortesia: Vorrei un caffè, per favore.","Arrependimentos (passado): Se avessi studiato, avrei passato l''esame. (terceira condicional)"]'::jsonb, '["Usar o indicativo em vez do congiuntivo: *Se ho tempo, viaggio* em vez de *Se avessi tempo, viaggerei*.","Usar o condizionale na oração com ''se'': *Se avrei tempo, viaggerei* (errado). O condizionale só vai na oração principal.","Confundir o congiuntivo imperfetto com o condizionale: *Se sarebbe possibile* em vez de *Se fosse possibile*.","Esquecer de concordar o verbo: *Se noi avesse tempo* em vez de *Se noi avessimo tempo*.","Usar a forma contraída ''dovrei'' indevidamente na oração com ''se''."]'::jsonb, '["O congiuntivo imperfetto é usado para situações hipotéticas no presente ou futuro.","O condizionale semplice é usado na oração principal para expressar a consequência.","A ordem das orações pode ser invertida: Viaggerei di più se avessi tempo.","A terceira condicional (passado) usa congiuntivo trapassato e condizionale composto, mas não é o foco desta lição.","A forma ''se fossi in te'' é muito usada para dar conselhos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

