insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-7210708ab242', 'it', 'B2', 'Expanded Relatives: Relative Pronouns in Complex Sentences', 'Nesta unidade, você vai aprender a usar pronomes relativos (che, cui, il quale/la quale, chi) para criar frases complexas e naturais. Esses pronomes ajudam a conectar ideias, evitar repetições e tornar seu italiano mais fluente e preciso.', 'Os pronomes relativos substituem um substantivo mencionado anteriormente (o antecedente). ''Che'' é invariável e usado para sujeito ou objeto direto (ex.: Il libro che leggo). ''Cui'' é usado após preposições (ex.: La città in cui vivo). ''Il quale/la quale'' concorda em gênero e número com o antecedente e pode ser usado após preposições (ex.: Il ragazzo con il quale parlo). ''Chi'' significa ''aquele que'' e é usado sem antecedente (ex.: Chi non risica non rosica).', '["Usamos ''che'' para sujeito ou objeto direto: ''La persona che parla'' (a pessoa que fala).","Usamos ''cui'' com preposições: ''Il paese in cui sono nato'' (o país em que nasci).","Usamos ''il quale/la quale'' para evitar ambiguidade ou em registro formal: ''Il datore di lavoro, il quale è molto severo...''","Usamos ''chi'' para generalizações: ''Chi studia passa l''esame'' (quem estuda passa no exame).","Podemos omitir ''che'' em alguns casos informais, mas na escrita formal é sempre usado."]'::jsonb, '["Confundir ''che'' e ''cui'' sem preposição: ''La persona cui ho visto'' é incorreto, deve ser ''che ho visto''.","Usar ''il quale'' sem concordância: ''Le persone la quale...'' deve ser ''le quali''.","Esquecer a preposição antes de ''cui'': ''La città cui vivo'' deve ser ''in cui vivo''.","Usar ''chi'' com antecedente explícito: ''Il ragazzo chi parla'' é incorreto, deve ser ''che parla''.","Colocar vírgula antes de ''che'' quando é essencial para o sentido: ''Il libro, che ho comprato'' muda o significado."]'::jsonb, '["Na fala, ''che'' é muito comum; ''il quale'' é mais formal.","Preste atenção se o pronome relativo é sujeito ou objeto para não confundir.","Em frases com preposição, use sempre ''cui'' ou ''il quale''.","Nas relativas restritivas, não use vírgula; nas explicativas, use.","Pratique transformar duas frases simples em uma complexa."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

