insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-284cbd3f9cdd', 'it', 'B2', 'CI e NE: Pronomi Combinati e Usi Idiomatici', 'Nesta unidade, você vai aprofundar o uso de dois pronomes muito especiais do italiano: ''ci'' e ''ne''. Além de seus usos mais básicos (ci = ''nós'', ''lá''; ne = ''disso'', ''daí''), eles aparecem em expressões fixas e combinações que dão um tom mais natural e fluente à fala. Vamos explorar como usá-los em contextos do dia a dia, como ''c''è'', ''non ne posso più'', ''che ne dici?'' e ''ci penso io''.', '''Ci'' e ''ne'' podem ser combinados com pronomes de objeto direto (lo, la, li, le) e indireto (mi, ti, gli, le, ci, vi) para formar pronomes duplos. ''Ci'' pode se tornar ''ce'' e ''ne'' permanece ''ne''. Exemplos: ''ce lo'' (a nós, isso), ''te ne'' (a ti, disso). Em expressões idiomáticas, ''ci'' e ''ne'' têm significados específicos que devem ser memorizados.', '[{"example":"Vado a Roma. Ci vado domani.","explanation":"Substitui ''a Roma'' (lugar).","title":"CI como pronome de lugar"},{"example":"Abbiamo il libro. Ce l''abbiamo.","explanation":"Quando ''ci'' (a nós) combina com ''lo'', vira ''ce lo''.","title":"CE como forma combinada com objeto direto"},{"example":"Quanti libri hai? Ne ho tre.","explanation":"Substitui ''di libri''.","title":"NE como partitivo"},{"example":"Non ne posso più!","explanation":"Significa ''estou farto''.","title":"NE em expressões idiomáticas"},{"example":"Ci penso io.","explanation":"Significa ''eu cuido disso''.","title":"CI em expressões idiomáticas"}]'::jsonb, '[{"example":"Maria ci vuole bene. (a noi)","explanation":"O contexto determina o significado.","title":"Confundir ''ci'' (a nós) com ''ci'' (lá)"},{"example":"Vado al cinema. *Ne vado.","explanation":"Para lugar, use ''ci'': ''Ci vado.''","title":"Usar ''ne'' no lugar de ''ci'' para lugares"},{"example":"Il libro? *Ci lo diamo.","explanation":"O correto é ''Ce lo diamo.''","title":"Esquecer a combinação ''ce lo''"},{"example":"Ne ho abbastanza.","explanation":"Não é ''tenho disso suficiente'', mas ''estou cheio''.","title":"Traduzir literalmente expressões com ''ne''"}]'::jsonb, '["Em italiano falado, ''ci'' e ''ne'' são frequentemente usados em combinações que não têm equivalente direto no português.","Atenção à posição: em tempos compostos, o particípio passado concorda com o pronome objeto: ''Ce l''ho detta'' (a história).","Algumas expressões são fixas: ''non c''è problema'', ''che ne so?''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

