insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-a6af10d7b941', 'it', 'B2', 'Connettivi Argomentativi in Italiano (B2)', 'Nesta unidade, você vai aprender a usar conectores argumentativos em italiano para organizar ideias, apresentar opiniões e contrapor pontos de vista de forma clara e coesa. Esses conectores são essenciais para escrever textos argumentativos e participar de discussões formais, como em ambientes acadêmicos ou profissionais.', 'Os conectores argumentativos são palavras ou expressões que ligam frases e parágrafos, estabelecendo relações lógicas como causa, consequência, contraste, adição e conclusão. Principais conectores:', '["Perché, poiché, siccome (causa): ''Non sono uscito perché pioveva.''","Quindi, perciò, di conseguenza (consequência): ''Ha piovuto tutto il giorno, quindi siamo rimasti a casa.''","Ma, però, tuttavia, mentre (contraste): ''Mi piace la pizza, ma oggi preferisco la pasta.''","Inoltre, oltre a ciò, inoltre (adição): ''Il progetto è interessante; inoltre, è realizzabile.''","In conclusione, per concludere, in sintesi (conclusão): ''In conclusione, ritengo che l''idea sia valida.''"]'::jsonb, '["Confondere ''perciò'' e ''poiché'': ''perciò'' significa ''portanto'' (consequência), ''poiché'' significa ''porque'' (causa).","Usare ''ma'' e ''però'' insieme: ''Ma però'' é redundante; escolha um deles.","Posicionar ''tuttavia'' no início da frase sem vírgula: ''Tuttavia, non sono d''accordo.''","Usar ''in oltre'' em vez de ''inoltre'' (separado vs. junto)."]'::jsonb, '["Na escrita formal, prefira ''tuttavia'' a ''però''.","''Siccome'' é usado principalmente no início da frase e indica causa bem conhecida.","''Mentre'' além de contraste, também pode indicar simultaneidade.","Os conectores podem ser usados no início de parágrafo para organizar o discurso."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

