insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-1ba07a01951a', 'it', 'B2', 'Registro e Variazione Regionale nell''Italiano', 'Nesta unidade, você vai explorar como o italiano varia de acordo com o contexto (registro) e a região (variação diatópica). Vamos focar em diferenças entre linguagem formal e informal, e em alguns regionalismos comuns, especialmente do norte e do sul da Itália.', 'O registro se manifesta na escolha de palavras, estruturas gramaticais e pronúncia. A variação regional inclui diferenças lexicais (ex.: ''babbo'' vs ''papà'' para pai), fonéticas (ex.: pronúncia de ''c'' em certas áreas) e às vezes morfológicas. Para B2, é importante reconhecer essas variações e saber quando usar o registro formal ou informal.', '["Em contextos formais, como em uma entrevista de emprego, use ''Lei'' e formas de cortesia.","Em conversas informais, entre amigos, use ''tu'' e expressões coloquiais.","Reconhecer regionalismos como ''fregatura'' (norte) vs ''fregatura'' (sul) para golpe, ou ''anguria'' vs ''cocomero'' para melancia.","Em e-mails profissionais, prefira fórmulas como ''Cordiali saluti'' a ''Ciao''.","Ao viajar, adapte-se ao dialeto local, mas mantenha o italiano padrão para comunicação geral."]'::jsonb, '["Usar ''tu'' com estranhos em contextos formais.","Confundir regionalismos: ''adesso'' vs ''mo'' (no sul) para ''agora''.","Achar que o italiano padrão é falado igualmente em toda a Itália.","Usar gírias em situações formais.","Ignorar diferenças de entonação e vocabulário entre norte e sul."]'::jsonb, '["O italiano padrão é baseado no dialeto toscano, mas cada região tem sua variação.","Em contextos formais, é comum usar o passato remoto no sul, enquanto no norte se usa mais o passato prossimo.","A cortesia é importante: use ''Lei'' com desconhecidos e superiores.","Regionalismos podem ser lexicalmente diferentes, mas ambos são compreensíveis por falantes nativos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

