insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-165bb6c435de', 'it', 'B2', 'Past and Imperfect Subjunctive in Italian', 'Neste tópico, você vai aprender a usar o passato congiuntivo e o congiuntivo imperfetto em italiano. Esses tempos são usados para expressar dúvidas, desejos, incertezas e situações irreais no passado. Vamos focar na formação e nos usos principais, com exemplos práticos e exercícios para reforçar o aprendizado.', 'O congiuntivo imperfetto é formado a partir do tema do infinitivo, removendo as terminações -are, -ere, -ire e adicionando as desinências específicas: para -are: -assi, -assi, -asse, -assimo, -aste, -assero; para -ere: -essi, -essi, -esse, -essimo, -este, -essero; para -ire: -issi, -issi, -isse, -issimo, -iste, -issero. Por exemplo: ''parlare'' > parlassi; ''credere'' > credessi; ''partire'' > partissi. O passato congiuntivo é formado pelo congiuntivo imperfetto do verbo ''essere'' ou ''avere'' seguido do particípio passado do verbo principal. Por exemplo: ''che io abbia parlato'' ou ''che io fossi andato'' (com verbos de movimento que usam ''essere'').', '["Para expressar desejos ou vontades no passado: ''Speravo che Maria venisse alla festa.''","Para expressar dúvidas ou incertezas sobre ações passadas: ''Non pensavo che avessi finito il lavoro.''","Para expressar situações irreais ou hipotéticas no passado: ''Se avessi tempo, andrei al cinema, ma non è possibile.''","Após expressões impessoais de opinião, como ''era necessario che'', ''era importante che''.","Após conjunções que indicam finalidade, tempo, condição, etc., como ''benché'', ''affinché'', ''prima che''."]'::jsonb, '["Usar o indicativo em vez do subjuntivo após expressões de dúvida ou desejo.","Confundir o passato prossimo com o passato congiuntivo na conjugação.","Errar a escolha entre ''essere'' e ''avere'' como auxiliares no passato congiuntivo.","Usar o subjuntivo após conjunções que não exigem, como ''dopo che''.","Não concordar corretamente o particípio passado com o sujeito quando se usa ''essere''."]'::jsonb, '["O congiuntivo imperfetto é frequentemente usado em frases condicionais com ''se'', para expressar uma condição irreal no presente.","O passato congiuntivo é usado para expressar ações completas no passado em relação ao verbo principal.","Em italiano moderno, especialmente na fala, o congiuntivo às vezes é substituído pelo indicativo, mas em contextos formais e escritos ainda é obrigatório.","Aprenda os verbos irregulares comuns do congiuntivo imperfetto, como ''essere'' (fossi), ''fare'' (facessi), ''dare'' (dessi)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

