insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-7fe74594f026', 'it', 'B2', 'Sequenza Temporale: Il Trapassato Prossimo e la Concordanza dei Tempi', 'Nesta unidade, vamos explorar a sequência temporal em italiano, focando no uso do Trapassato Prossimo e na concordância dos tempos verbais em frases complexas. Você aprenderá a expressar ações passadas que ocorreram antes de outras ações passadas, usando os tempos verbais de forma adequada. Este conhecimento é essencial para narrar histórias, descrever experiências e falar sobre eventos passados com precisão.', 'O Trapassato Prossimo é formado com o imperfetto do verbo essere ou avere + o particípio passado do verbo principal. Escolha entre essere e avere de acordo com as regras usuais (verbos transitivos usam avere, verbos intransitivos de movimento ou estado usam essere, etc.). Exemplos: ''Quando sono arrivato, Maria era già partita.'' (Quando cheguei, Maria já tinha partido). Observe a concordância do particípio passado com o sujeito quando se usa essere.', '["Para expressar uma ação passada que ocorreu antes de outra ação passada: ''Avevo già mangiato quando sei arrivato.''","Para descrever uma causa passada de um evento passado: ''Non è venuto alla festa perché aveva perso il treno.''","Em narrativas para estabelecer a ordem dos eventos: ''Dopo che aveva finito i compiti, uscì con gli amici.''","Com as conjunções temporais come ''dopo che'', ''quando'', ''appena'' para indicar anterioridade."]'::jsonb, '["Usar o passato prossimo em vez do trapassato prossimo quando a ação é anterior a outra passada: ''Quando sono arrivato, Maria è partita'' em vez de ''era già partita''.","Errar a escolha entre essere e avere: ''Sono mangiato'' em vez de ''Ho mangiato''.","Não concordar o particípio passado com o sujeito quando se usa essere: ''Sono partita'' (feminino) corretamente, mas ''Sono partito'' para masculino.","Esquecer de usar o imperfetto do auxiliar, usando o presente ou passato prossimo do auxiliar: ''Ho avuto mangiato'' em vez de ''Avevo mangiato''."]'::jsonb, '["O Trapassato Prossimo é frequentemente usado com expressões de tempo como ''già'', ''appena'', ''ancora'', ''da poco''.","Na língua falada, às vezes o trapassato é substituído pelo passato prossimo, mas em contextos formais e escritos, é importante usar corretamente.","Cuidado com a diferença entre ''era'' (imperfetto) e ''fu'' (passato remoto) quando se fala de eventos históricos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

