insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-22bc57d1dc1b', 'it', 'B2', 'Unreal Conditionals in Italian (B2)', 'Nesta lição, você vai aprender a usar os condicionais irreais em italiano para falar de situações hipotéticas, imaginárias ou contrafactuais. Vamos explorar o segundo e o terceiro condicional, estruturas essenciais para expressar desejos, conselhos e arrependimentos. Ao final, você será capaz de construir frases complexas e naturais, ampliando sua fluência e precisão.', 'Segundo condicional (presente hipotético): Se + imperfetto congiuntivo, condizionale semplice. Ex.: Se avessi tempo, viaggerei di più. (Se eu tivesse tempo, viajaria mais.) Terceiro condicional (passado hipotético): Se + trapassato congiuntivo, condizionale composto. Ex.: Se avessi saputo, sarei venuto. (Se eu soubesse, teria vindo.) Casos mistos: Se + imperfetto congiuntivo, condizionale composto. Ex.: Se lavorassi di più, avresti finito. (Se trabalhasse mais, teria terminado.)', '["Para expressar desejos ou situações improváveis no presente ou futuro: Se vincessi alla lotteria, comprerei una casa al mare.","Para falar de situações irreais ou contrafatuais no passado: Se avessi studiato, avrei passato l''esame.","Para dar conselhos de forma educada (com o verbo ''dovere'' ou ''potere'' no condizionale): Se fossi in te, parlerei con il direttore.","Para expressar arrependimentos ou críticas sobre o passado: Se non avessi dimenticato le chiavi, non saremmo rimasti fuori."]'::jsonb, '["Usar o presente do indicativo na cláusula ''se'': *Se ho tempo, viaggerei* → correto: Se avessi tempo, viaggerei.","Confundir o uso do imperfeito do subjuntivo com o condicional na cláusula ''se'': *Se sarei ricco* → correto: Se fossi ricco.","Esquecer de usar o subjuntivo após ''se'' em situações hipotéticas.","Usar o segundo condicional para eventos passados irreais: *Se avevo studiato* → correto: Se avessi studiato.","Na mistura condicional, não ajustar os tempos corretamente: *Se avessi studiato, passerei l''esame* → correto: Se avessi studiato, avrei passato l''esame."]'::jsonb, '["Em italiano, a conjunção ''se'' é sempre seguida do subjuntivo (congiuntivo) em frases condicionais irreais.","O condizionale semplice corresponde ao futuro do pretérito em português, e o composto ao futuro do pretérito composto.","Na linguagem falada, às vezes o imperfeito do indicativo é usado no lugar do subjuntivo, mas no nível B2 é importante empregar a forma correta.","Para fazer perguntas hipotéticas, usa-se a mesma estrutura: ''Cosa faresti se...?''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

