insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-69e6530de1a5', 'it', 'B2', 'Reported Speech: Presente e Passato', 'Nesta lição, você aprenderá como transformar frases ditas por outras pessoas em discurso indireto, tanto no presente quanto no passado. Vamos focar nas mudanças necessárias nos tempos verbais e pronomes, com exemplos práticos para o dia a dia.', 'Para formar o discurso indireto, usamos geralmente um verbo introdutor como ''dire'', ''chiedere'' ou ''rispondere'', seguido da conjunção ''che'' e da informação reformulada. No presente, o verbo introduzido permanece no mesmo tempo (ex.: ''Marco dice che è stanco''). No passado, o verbo no discorso indireto muda: se ouvimos ''sono stanco'' no presente, no passado torna-se ''era stanco''. As mudanças principais envolvem o tempo verbal, os pronomes pessoais e possessivos, e expressões de tempo e lugar.', '["Relatar o que alguém disse no presente sem mudança de tempo verbal.","Relatar uma afirmação feita no passado, com adaptação do tempo verbal.","Relatar uma pergunta indireta.","Relatar uma ordem ou pedido.","Relatar uma sugestão ou conselho."]'::jsonb, '["Manter o tempo verbal original sem adaptação quando o verbo introdutor está no passado.","Esquecer de ajustar os pronomes pessoais e possessivos de acordo com o novo contexto.","Confundir as mudanças de tempo (presente para imperfeito, futuro para condicional).","Não usar a conjunção ''che'' ou ''se'' nas perguntas indiretas.","Traduzir literalmente do inglês, mantendo a estrutura do direct speech."]'::jsonb, '["No discorso indireto, ''oggi'' pode virar ''quel giorno'' e ''domani'' vira ''il giorno dopo''.","O verbo ''dire'' pode ser substituído por outros como ''raccontare'', ''affermare'', ''rispondere'' para maior precisão.","Nas perguntas indiretas, a ordem das palavras muda e não usamos o ponto de interrogação.","Com ordens ou pedidos, usamos ''di'' + infinitivo, ex.: ''Mi ha detto di chiamarlo''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

