insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-it-b2-69e6530de1a5-exercise-05', 'it', 'B2', 'Ordem no discorso indiretto', 'Ordini e richieste usam ''di'' + infinito.', 'Original: ''Chiudi la porta.'' -> Mi ha detto di chiudere la porta.', 'Transforme: ''Non fumare qui.'' (Il medico mi ha detto...)', '["Il medico mi ha detto di non fumare qui.","Il medico mi ha detto che non fumo qui.","Il medico mi ha detto non fumare qui.","Il medico mi ha detto di non fumare lì."]'::jsonb, 3, 5, true, 'generated-grammar-it-b2-69e6530de1a5')
