insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-5da73cbce396', 'it', 'B2', 'Frasi Relative Espansive: ''Il che'' e ''Grazie al quale''', 'Nesta unidade, você vai aprender a usar frases relativas expansivas, que adicionam informações extras sobre uma ideia ou situação inteira. Vamos focar em ''il che'' e ''grazie al quale'', que são comuns em italiano B2 para conectar ideias de forma mais sofisticada.', 'As frases relativas expansivas são formadas com pronomes relativos como ''il che'' (o que) e ''grazie al quale'' (graças ao qual). ''Il che'' refere-se a toda a oração anterior, enquanto ''grazie al quale'' (com variações como ''grazie alla quale'', ''grazie ai quali'') refere-se a um substantivo específico e indica causa ou meio. Exemplos: ''Ha piovuto tutto il giorno, il che ha rovinato la gita.'' (Choveu o dia inteiro, o que estragou o passeio.) ''Ha studiato molto, grazie al quale ha superato l''esame.'' (Estudou muito, graças ao que passou no exame.)', '["Usar ''il che'' para comentar sobre uma ação ou fato inteiro expresso na oração anterior.","Usar ''grazie al quale'' para indicar que algo foi possível devido a um elemento específico mencionado antes.","Empregar essas estruturas para tornar o discurso mais coeso e formal, típico do nível B2.","Diferenciar ''il che'' (referência à frase inteira) de ''che'' (referência a um substantivo específico)."]'::jsonb, '["Usar ''che'' no lugar de ''il che'' quando a referência é a oração inteira.","Confundir ''grazie al quale'' com ''grazie a cui'' (menos comum).","Esquecer a concordância de gênero e número em ''grazie al quale'' (ex: ''grazie alla quale'' para um substantivo feminino).","Colocar vírgula incorretamente: antes de ''il che'' e ''grazie al quale'' em geral há vírgula."]'::jsonb, '["Atenção: ''il che'' é invariável e sempre se refere a uma oração inteira.","Em contextos informais, pode-se usar ''che'' no lugar de ''il che'', mas no B2 é importante usar a forma padrão.","Pratique a entonação ao ler frases com essas estruturas para dar fluência."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

