insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-efb5c8b750b9', 'it', 'B2', 'Nominalização em Italiano: Transformar Verbos em Substantivos', 'Nesta lição, você vai aprender a transformar verbos em substantivos, uma habilidade essencial para enriquecer seu vocabulário e tornar sua comunicação mais formal e natural. A nominalização é amplamente usada em contextos acadêmicos, profissionais e na imprensa. Você verá os principais sufixos (-zione, -mento, -aggio, -tura) e como usá-los corretamente, evitando erros comuns.', 'Para nominalizar um verbo em italiano, adicione um sufixo à raiz do verbo. Os principais sufixos são: -zione (formare → formazione), -mento (cambiare → cambiamento), -aggio (correggere → correzione, ma anche, ad esempio, montare → montaggio) e -tura (aprire → apertura). Alguns substantivos são formados de maneira irregular (decidere → decisione, scegliere → scelta). A escolha do sufixo depende do verbo e não há uma regra fixa; é importante memorizar as formas mais comuns. Observe que a nominalização geralmente mantém o radical do verbo, mas às vezes ocorrem pequenas alterações (leggere → lettura, prendere → presa).', '["Para expressar ações de forma substantiva: ''La produzione di olio è aumentata.'' (produrre → produzione)","Para tornar a linguagem mais formal: ''La riunione ha discusso la creazione di un nuovo progetto.'' (creare → creazione)","Para nomear processos: ''Il cambiamento climatico è un problema globale.'' (cambiare → cambiamento)","Para descrever atividades: ''Il montaggio dei mobili richiede tempo.'' (montare → montaggio)","Para indicar resultados ou instrumentos: ''La scrittura di questo libro è durata due anni.'' (scrivere → scrittura, embora irregular)"]'::jsonb, '["Usar o gerúndio em vez do substantivo: ''La mangiare'' em vez de ''il mangiare'' ou ''la nutrizione''.","Tentar aplicar um sufixo genérico: nem todos os verbos aceitam -zione ou -mento, como ''correre'' → ''corsa'' e não ''corrimento''.","Confundir gênero: alguns substantivos são masculinos (-mento) e outros femininos (-zione, -tura).","Esquecer as irregularidades: ''scegliere'' → ''scelta'', ''decidere'' → ''decisione''."]'::jsonb, '["A nominalização é mais comum na língua escrita e em contextos formais.","Alguns sufixos têm significados específicos: -tura pode indicar instrumento (apertura, chiusura) e -aggio pode indicar adaptação (montaggio).","Observe a ortografia: verbos terminados em -are geralmente formam substantivos em -azione; verbos em -ere podem usar -mento ou -imento (avvenimento).","Aprenda as nominalizações em grupos temáticos para facilitar a memorização."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

