insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-6e86aaec8603', 'it', 'B2', 'Connettivi Argomentativi', 'Neste tópico, você vai aprender a usar conectores argumentativos em italiano para organizar ideias, apresentar opiniões e justificar pontos de vista, tanto na fala quanto na escrita. Esses conectores são essenciais para produzir textos coerentes e convincentes, especialmente em contextos formais ou acadêmicos.', 'Os conectores argumentativos são palavras ou expressões que ligam frases e parágrafos, estabelecendo relações lógicas como causa, consequência, contraste, adição, conclusão e exemplificação. Alguns dos mais comuns são: ''innanzitutto'' (primeiramente), ''inoltre'' (além disso), ''tuttavia'' (contudo), ''quindi'' (portanto), ''perché'' (porque), ''per esempio'' (por exemplo), ''in conclusione'' (em conclusão). Eles podem aparecer no início da frase, seguidos de vírgula, ou no meio dela.', '["Para introduzir um argumento: ''Innanzitutto, vorrei dire che...''","Para acrescentar informações: ''Inoltre, è importante considerare...''","Para expressar contraste: ''Tuttavia, ci sono anche degli svantaggi...''","Para indicar consequência: ''Quindi, dobbiamo agire subito...''","Para justificar: ''Perché il traffico è un problema serio...''","Para dar exemplos: ''Per esempio, a Milano il trasporto pubblico è molto usato...''","Para concluir: ''In conclusione, possiamo affermare che...''"]'::jsonb, '["Usare ''quindi'' ao invés de ''tuttavia'' para expressar contraste.","Esquecer a vírgula após o conectivo no início da frase.","Confundir ''perché'' com ''perciò'': ''perché'' introduz causa, ''perciò'' consequência.","Usar ''inoltre'' para introduzir uma ideia contrária em vez de ''tuttavia''.","Repetir o mesmo conectivo muitas vezes, tornando o texto monótono."]'::jsonb, '["Em italiano, os conectivos podem ser formais ou informais; ''comunque'' é mais coloquial, enquanto ''tuttavia'' é mais formal.","A posição do conectivo pode variar, mas no início da frase é mais comum.","Alguns conectivos podem ser usados tanto na fala quanto na escrita, mas alguns são mais típicos da escrita acadêmica."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

