insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-d0656a65a4e0', 'it', 'B2', 'Frasi Relative Estese: Il quale, la quale, i quali, le quali', 'Nesta unidade, você vai aprender a usar os pronomes relativos ''il quale'', ''la quale'', ''i quali'' e ''le quali'', que são formas mais formais e específicas dos relativos ''che'' e ''cui''. Eles são usados para conectar ideias, evitar repetições e dar mais clareza ao texto, especialmente em contextos escritos ou formais.', 'Os pronomes relativos ''il quale'', ''la quale'', ''i quali'', ''le quali'' concordam em gênero e número com o substantivo a que se referem. São usados principalmente como sujeito ou objeto da frase relativa, e podem ser precedidos de preposições (especialmente ''di'', ''a'', ''da'', ''in'', ''con'', ''su''). Exemplos:
- Il libro, il quale è sul tavolo, è mio. (O livro, que está sobre a mesa, é meu.)
- La ragazza, la quale ho visto ieri, è simpatica. (A garota, que vi ontem, é simpática.)
- I ragazzi, i quali studiano molto, passeranno l''esame. (Os rapazes, que estudam muito, passarão no exame.)
- Le città, le quali visitiamo, sono bellissime. (As cidades, que visitamos, são lindíssimas.)
Precedidos de preposição:
- La persona di cui ti ho parlato = La persona della quale ti ho parlato. (A pessoa de quem te falei.)
- Il paese in cui vivo = Il paese nel quale vivo. (O país em que vivo.)
Use-os para evitar ambiguidades quando ''che'' pode se referir a mais de um substantivo.', '["Para evitar ambiguidade quando ''che'' pode se referir a mais de um substantivo na frase.","Em contextos formais, como escrita acadêmica, jornalística ou profissional.","Após preposições, como ''di'', ''a'', ''da'', ''in'', ''con'', ''su'', para maior clareza.","Para dar ênfase ou estilo mais elegante ao texto."]'::jsonb, '["Usar ''il quale'' no lugar de ''che'' em contextos informais, tornando o discurso artificial.","Não concordar o pronome com o gênero e número do substantivo (ex.: ''la quale'' com substantivo masculino).","Esquecer de usar a preposição antes do pronome quando necessário (ex.: ''la quale'' em vez de ''della quale'').","Usar ''il quale'' como objeto direto sem necessidade, quando ''che'' seria suficiente em linguagem coloquial."]'::jsonb, '["Em italiano moderno, ''che'' é mais comum na fala, enquanto ''il quale'' é mais usado na escrita formal.","Os pronomes relativos variáveis são frequentemente precedidos por preposições, formando combinações como ''del quale'', ''alla quale'', ''dal quale'' etc.","Preste atenção: ''il quale'' pode ser usado como sujeito, especialmente para evitar ambiguidade."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

