insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-b6be4368fef2', 'it', 'B2', 'Connettivi Argomentativi (B2)', 'Nesta unidade, você vai aprender a usar conectores argumentativos em italiano para organizar ideias, expressar opiniões e contrapor argumentos de forma clara e eficaz. Esses conectores são essenciais para produzir textos e discursos mais sofisticados, típicos do nível B2.', 'Os conectores argumentativos são palavras ou expressões que ligam frases e parágrafos, estabelecendo relações lógicas como causa, consequência, oposição, concessão e conclusão. Eles podem aparecer no início da frase, seguidos de vírgula, ou no meio, dependendo da estrutura. Exemplos: ''infatti'' (na verdade), ''tuttavia'' (no entanto), ''quindi'' (portanto), ''nonostante'' (apesar de), ''dunque'' (logo), ''anzi'' (pelo contrário).', '["Para introduzir uma justificativa ou explicação: ''Non sono venuto alla festa, infatti avevo molto lavoro.''","Para indicar oposição: ''Il film era interessante, tuttavia un po'' lungo.''","Para expressar consequência: ''Ha piovuto tutto il giorno, quindi siamo rimasti a casa.''","Para introduzir uma concessão: ''Nonostante il freddo, siamo andati a fare una passeggiata.''","Para concluir um raciocínio: ''Dunque, possiamo dire che l''esperienza è stata positiva.''","Para corrigir ou enfatizar: ''Non è difficile, anzi, è molto semplice.''"]'::jsonb, '["Usar ''infatti'' no lugar de ''tuttavia'': ''Non è ricco, infatti è generoso.'' (errado – o correto seria ''tuttavia'').","Confundir ''quindi'' e ''dunque'' com ''infatti'': ''Era stanco, quindi non è uscito.'' (consequência correta: ''quindi'').","Esquecer de usar o subjuntivo após ''nonostante'': ''Nonostante sia stanco, esce.'' (correto: ''Nonostante sia stanco, esce.'').","Posicionar o conector de forma inadequada: ''Tuttavia, era contento.'' (mais natural: ''Era contento, tuttavia...'').","Usar ''anzi'' sem o sentido de contradição: ''Non mi piace la pizza, anzi la mangio spesso.'' (errado – ''anzi'' indica correção de uma negação)."]'::jsonb, '["Embora ''quindi'' e ''dunque'' sejam sinônimos em muitos contextos, ''dunque'' é um pouco mais formal.","Atenção à ordenação: em italiano, os conectores frequentemente aparecem no início da segunda frase, muitas vezes precedidos de ponto ou vírgula.","Para não soar repetitivo, alterne o uso dos conectores: ''infatti'', ''dunque'', ''tuttavia'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

