insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-72cc1737219c', 'it', 'B2', 'Past and Imperfect Subjunctive in Italian', 'Nesta lição, você vai aprender a formar e usar o passato congiuntivo (passado do subjuntivo) e o congiuntivo imperfetto (imperfeito do subjuntivo) em italiano. Esses tempos são essenciais para expressar incerteza, desejo, emoção ou opinião sobre ações passadas ou simultâneas em relação ao passado. Você verá como eles se encaixam em frases complexas e como se diferenciam dos tempos do indicativo.', 'Para formar o congiuntivo imperfetto, pegue a terceira pessoa do plural do passato remoto (para verbos regulares) e adicione as terminações: -ssi, -ssi, -sse, -ssimo, -ste, -ssero. Exemplo: ''parlare'' → ''parlarono'' → che io parlassi, che tu parlassi, che lui parlasse, che noi parlassimo, che voi parlaste, che loro parlassero. Para o passato congiuntivo, use o congiuntivo presente do verbo ''avere'' ou ''essere'' (conforme o auxiliar) seguido do particípio passado: che io abbia parlato, che tu sia andato/a, etc. Verbos irregulares comuns no congiuntivo imperfetto: essere → fossi, avere → avessi, fare → facessi, bere → bevessi, dire → dicessi.', '["Uso do congiuntivo imperfetto para expressar uma ação passada simultânea a outra ação no passado: ''Pensavo che Luca fosse a casa.''","Uso do congiuntivo imperfetto em frases condicionais irreais (segundo tipo): ''Se avessi tempo, verrei da te.''","Uso do congiuntivo imperfetto após expressões impessoais no passado: ''Era meglio che partissimo prima.''","Uso do passato congiuntivo para indicar uma ação passada em relação a um verbo principal no passado: ''Speravo che tu avessi ricevuto il mio messaggio.''","Uso do passato congiuntivo em expressões de desejo ou dúvida sobre o passado: ''Non credo che Maria abbia detto la verità.''"]'::jsonb, '["Confundir o uso do congiuntivo imperfetto com o condizionale simples em frases com ''se''.","Usar o indicativo em vez do congiuntivo após ''pensare'', ''credere'', ''sperare'' no passado.","Errar a escolha do auxiliar no passato congiuntivo com verbos de movimento (usar ''essere'' não ''avere'').","Esquecer a concordância do particípio passado com o sujeito quando se usa ''essere'' como auxiliar."]'::jsonb, '["A diferença entre o congiuntivo imperfetto e o passato congiuntivo está na relação temporal: o primeiro indica simultaneidade com o passado, o segundo indica anterioridade.","O congiuntivo imperfetto é frequentemente usado na construção do período hipotético da possibilidade (segundo tipo).","Verbos que expressam opinião, desejo, dúvida, emoção, e expressões impessoais como ''è giusto'', ''è possibile'' requerem o congiuntivo nas orações subordinadas.","Atenção à forma ''fossi'' para todas as pessoas: ''io fossi'', ''tu fossi'', ''lui fosse'' (mas ''tu fossi'' é igual a ''io fossi'', e a terceira pessoa é ''fosse'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

