insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-73b7c491761b', 'it', 'B2', 'Sequenza Temporale nella Narrazione', 'Nesta lição, você vai aprender a usar corretamente os tempos verbais para narrar eventos no passado, presente e futuro. Vamos focar na sequência temporal, ou seja, como combinar passato prossimo, imperfetto, trapassato prossimo e futuro para organizar uma história de forma clara e natural.', 'A sequência temporal envolve o uso dos seguintes tempos:
- Passato prossimo: para ações concluídas no passado (ho mangiato).
- Imperfetto: para ações habituais ou descrições no passato (mangiavo).
- Trapassato prossimo: para uma ação anterior a outra no passado (avevo mangiato).
- Futuro semplice: para ações futuras (mangerò).
- Futuro anteriore: para ações futuras que acontecerão antes de outra (avrò mangiato).
A escolha do tempo depende da relação temporal entre os eventos.', '["Descrever a cena com imperfetto e inserir eventos com passato prossimo.","Expressar uma ação passada anterior a outra com trapassato prossimo.","Planejar ações futuras usando futuro semplice.","Indicar uma ação futura que ocorrerá antes de outra com futuro anteriore.","Narrar hábitos passados com imperfetto.","Combinar passato prossimo e imperfetto para dar fundo e ação.","Usar o presente para verdades gerais em narrações atemporais."]'::jsonb, '["Confundir passato prossimo e imperfetto para ações concluídas vs. habituais.","Usar o trapassato prossimo sem contexto de anterioridade.","Aplicar o futuro anteriore sem a necessidade de indicar uma ação anterior.","Ignorar a concordância dos tempos em períodos compostos.","Usar o imperfetto para ações pontuais concluídas.","Esquecer de que o futuro anteriore geralmente é usado com ''quando'', ''dopo che'', etc."]'::jsonb, '["Use o imperfetto para descrever circunstâncias e o passato prossimo para eventos principais.","O trapassato prossimo é comum em orações com ''quando'', ''dopo che'', ''appena''.","Para o futuro, o futuro anteriore é usado com ''quando'' + futuro semplice.","Atenção aos verbos modais: ''dovevo'' vs. ''ho dovuto'' têm nuances diferentes.","Em narrativas, a ordem cronológica pode ser alterada com o uso do trapassato prossimo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

