insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-88e5dd66686f', 'it', 'B2', 'Periodo Ipotetico dell''Irrealtà', 'No nível B2, você vai aprofundar o uso do período hipotético para expressar situações irreais ou impossíveis no presente e no futuro. Vamos focar na estrutura com o congiuntivo imperfetto e o condizionale presente, que usamos para falar de sonhos, conselhos e hipóteses contrafactuais, como em ''Se io fossi ricco, comprerei una casa al mare''.', 'O período hipotético da irrealtà (tipo 2) é formado por: SE + CONGIUNTIVO IMPERFETTO, + CONDIZIONALE PRESENTE. O congiuntivo imperfetto é usado para ações não reais no presente ou futuro; o condizionale presente indica a consequência possível. Veja os verbos mais comuns: essere -> fossi/fossimo; avere -> avessi/avessimo; parlare -> parlassi/parlassimo; prendere -> prendessi/prendessimo; partire -> partissi/partissimo.', '["Para expressar desejos irreais no presente: ''Se avessi tempo, viaggerei di più.''","Para dar conselhos de forma educada: ''Se fossi in te, accetterei l''offerta.''","Para imaginar situações hipotéticas futuras improváveis: ''Se vincessi alla lotteria, smetterei di lavorare.''","Para criticar ou lamentar situações atuais: ''Se non facesse così tanto rumore, potrei studiare.''","Para formular convites ou propostas hipotéticas: ''Se tu volessi, potremmo andare al cinema.''"]'::jsonb, '["Usar o indicativo após ''se'' (ex.: ''Se ho tempo, andrei'' -> correto: ''Se avessi tempo, andrei'').","Confundir o congiuntivo imperfetto com o condizionale (ex.: ''Se sarei ricco'' -> correto: ''Se fossi ricco'').","Usar o condizionale na cláusula com ''se'' (ex.: ''Se vorrei, lo farei'' -> correto: ''Se volessi, lo farei'').","Esquecer de conjugar o congiuntivo na primeira pessoa plural (ex.: ''Se noi fossimo'' e não ''se noi eravamo'')."]'::jsonb, '["O congiuntivo imperfetto tem as mesmas terminações para -are, -ere, -ire: -assi, -essi, -issi.","Os verbos irregulares no congiuntivo imperfetto incluem essere (fossi), dare (dessi), stare (stessi), fare (facessi), bere (bevessi), dire (dicessi).","Na fala cotidiana, às vezes se usa o imperfetto indicativo no lugar do congiuntivo (ex.: ''Se lo sapevo, venivo''), mas isso é informal e deve ser evitado em contextos formais.","Para enfatizar a improbabilidade, pode-se usar ''se mai'' ou ''se per caso'' antes do congiuntivo (ex.: ''Se mai decidessi di partire, avvisami'').","O período hipotético da irrealtà é frequentemente usado em construções com ''come se'' (ex.: ''Parla come se fosse il capo'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

