insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-758be34d36c5', 'it', 'B2', 'Past Reported Speech (Discorso Indiretto al Passato)', 'Nesta lição, você aprenderá a relatar o que alguém disse no passado usando o discorso indireto (discorso indiretto). Vamos focar nas mudanças de tempos verbais, pronomes e expressões de tempo, que são essenciais para narrar conversas e pensamentos em italiano.', 'Para formar o discorso indiretto ao passado, geralmente começamos com um verbo introdutor no passato prossimo ou imperfetto (como ''ha detto'', ''diceva'', ''ha chiesto''). Em seguida, o tempo verbal da frase original muda: o presente vira imperfetto, o passato prossimo vira trapassato prossimo, e o futuro vira condizionale passato. Também é necessário ajustar pronomes (io -> lui/lei) e expressões de tempo (oggi -> quel giorno, domani -> il giorno dopo, adesso -> allora).', '["Para relatar o que alguém disse em uma conversa passada.","Para transmitir informações ou notícias ouvidas de outras pessoas.","Para narrar histórias ou eventos contados por alguém.","Para expressar pensamentos ou opiniões que foram ditos no passado."]'::jsonb, '["Manter o verbo no mesmo tempo da frase original, sem fazer as mudanças corretas.","Esquecer de alterar pronomes e possessivos (io -> lui, mio -> suo).","Não adaptar expressões de tempo e lugar (qui -> lì, oggi -> quel giorno).","Usar o congiuntivo em vez do indicativo em alguns casos, ou vice-versa."]'::jsonb, '["Se o verbo introdutor estiver no presente (dice), o tempo verbal da frase original permanece o mesmo.","Quando a frase relatada é uma pergunta, usamos ''se'' para perguntas sim/não e a palavra interrogativa para perguntas abertas (che, dove, perché, etc.).","Podemos usar a construção ''ha detto di + infinito'' para ordens e pedidos.","Lembre-se de que algumas expressões de tempo mudam: ''ieri'' -> ''il giorno prima'', ''adesso'' -> ''allora''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

