insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-2aab33492ce2', 'it', 'B2', 'La forma passiva e il costrutto causativo con ''fare''', 'Nesta unidade, você vai aprender a usar a forma passiva e o causativo com ''fare'' em italiano. A passiva é usada para focar na ação e não em quem a pratica, enquanto o causativo indica que você faz com que algo seja feito por outros. Vamos explorar a formação, os usos e os erros comuns, com exercícios para praticar.', 'Passiva: verbo essere + particípio passado do verbo principal, concordando em gênero e número com o sujeito. Ex.: ''La pizza è mangiata da Marco'' (A pizza é comida pelo Marco). O agente é introduzido por ''da''. Causativo: verbo fare + infinitivo do verbo principal, com o objeto que sofre a ação. Ex.: ''Marco fa riparare la macchina'' (O Marco faz consertar o carro). No causativo, o sujeito faz com que a ação seja realizada por outra pessoa, que pode ser explicitada com ''a'' ou ''da''.', '["Para enfatizar a ação em vez do agente (passiva).","Quando o agente é desconhecido ou irrelevante (passiva).","Para descrever processos ou hábitos (passiva).","Para indicar que você faz algo ser feito por outros (causativo).","Para expressar situações impessoais com ''si'' (passiva impessoal)."]'::jsonb, '["Confundir a escolha do auxiliar na passiva (sempre ''essere'').","Não concordar o particípio passado com o sujeito na passiva.","Usar ''per'' em vez de ''da'' para introduzir o agente.","No causativo, colocar o infinitivo no particípio passado.","Achar que o objeto do causativo é sempre o sujeito da ação."]'::jsonb, '["Na passiva, o agente pode ser omitido se não for importante.","O tempo verbal da passiva é expresso pelo verbo ''essere'' no tempo desejado.","O causativo também é usado com ''lasciare'' para significar ''deixar fazer''.","Em italiano formal, a passiva com ''si'' é comum em textos impessoais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

