insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-31a0e7b50905', 'it', 'B2', 'Frasi relative con ''cui'' (relative clauses with ''cui'')', 'Nesta lição, você vai aprender a usar o pronome relativo ''cui'' em orações relativas, que é essencial para conectar ideias e tornar seu italiano mais natural e fluente. Vamos explorar sua formação, seus usos, erros comuns e praticar com exercícios.', 'O pronome ''cui'' é invariável e é usado para substituir um antecedente (pessoa, cosa, luogo) quando seguido de uma preposição. Exemplos: ''la persona con cui parlo'' (a pessoa com quem falo), ''il paese in cui vivo'' (o país onde vivo), ''il motivo per cui parto'' (o motivo pelo qual parto). Estrutura: [antecedente] + [preposição] + cui + [frase]. A preposição pode ser qualquer uma (di, a, da, in, con, su, per, tra, fra) e pode ser articulada (como ''con cui'', ''in cui'', ''da cui'').', '["Para indicar lugar: ''La città in cui sono nato'' (A cidade onde nasci).","Para indicar meio ou companhia: ''Il ragazzo con cui studio'' (O rapaz com quem estudo).","Para indicar origem ou proveniência: ''Il paese da cui vengo'' (O país de onde venho).","Para indicar posse: ''La persona di cui parlo'' (A pessoa de quem falo).","Para indicar motivo ou causa: ''Il motivo per cui sono qui'' (O motivo pelo qual estou aqui)."]'::jsonb, '["Usar ''che'' em vez de ''cui'' após preposição: ''La persona che parlo'' (errado) vs. ''La persona con cui parlo'' (certo).","Esquecer a preposição: ''La città cui vivo'' (errado) vs. ''La città in cui vivo'' (certo).","Confundir ''cui'' com ''quale'': ''con il quale'' é possível, mas ''cui'' é mais comum; cuidado com o gênero e número.","Usar ''il cui'' para posse: ''La persona il cui nome non ricordo'' (a pessoa cujo nome não me lembro) é correto, mas não substitua ''cui'' por ''che'' nesses casos."]'::jsonb, '["''cui'' não tem variação de gênero ou número.","Quando a preposição ''con'' se combina com ''cui'', geralmente usa-se ''con cui'' (não ''cui'' sozinho).","Em registros formais, pode-se usar ''il quale/la quale/...'' com preposição, mas ''cui'' é mais comum e coloquial.","Em frases como ''il motivo per cui'', ''per cui'' pode significar ''portanto'' em contextos causais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

