insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-b2-4cbee74cf86a', 'it', 'B2', 'Nominalizzazione: da verbo a sostantivo', 'A nominalização é o processo de transformar verbos em substantivos, essencial para um discurso mais formal e abstrato. Nesta lição, você aprenderá a reconhecer e formar nominalizações comuns usando sufixos como -zione, -mento e -aggio, e como usá-las para enriquecer seu italiano em contextos profissionais e acadêmicos.', 'Em italiano, muitos verbos podem ser transformados em substantivos adicionando sufixos específicos. Aqui estão as regras mais comuns: 1) Verbos terminados em -are frequentemente formam substantivos com o sufixo -zione (ex: comunicare -> comunicazione). 2) Verbos terminados em -ere e -ire podem usar -mento (ex: credere -> credimento, agire -> agimento, embora ''credimento'' seja raro; ''agimento'' também, mas ''agire'' pode gerar ''azione''). Na prática, muitos verbos irregulares têm formas nominais próprias (ex: giungere -> giunzione). 3) Alguns verbos formam substantivos com -aggio (ex: atterrare -> atterraggio). 4) Outros sufixos incluem -anza (es: cambiare -> cambiamento, mas ''abbondanza'' de ''abbondare''), -ata (ex: camminata), -ura (ex: chiusura), -tà (ex: verità). É importante memorizar as formas mais comuns, pois nem todas seguem um padrão previsível.', '["Em contextos formais, como cartas comerciais ou discursos: preferimos ''La realizzazione del progetto'' em vez de ''realizzare il progetto''.","Para expressar conceitos abstratos e tornar o discurso mais conciso: ''L''apprendimento delle lingue è importante'' em vez de ''Imparare le lingue è importante''.","Em títulos e manchetes: ''La costruzione di un nuovo stadio'' em vez de ''Costruire un nuovo stadio''.","Para se referir a processos ou resultados em contextos técnicos ou acadêmicos: ''La trasformazione digitale''.","Em frases com uso de preposições, como ''la necessità di cambiare'' pode se tornar ''la necessità del cambiamento''."]'::jsonb, '["Erro: Usar o substantivo em vez do verbo em tempos compostos. Exemplo errado: ''Ho fatto la costruzione di una casa'' em vez de ''Ho costruito una casa''. A nominalização não deve ser usada com verbos auxiliares quando o verbo original era transitivo.","Erro: Escolher o sufixo errado. Exemplo: ''il cambiamento'' (não ''cambianza'') e ''la decisione'' (não ''decidimento'').","Erro: Confundir substantivos deverbais com adjetivos. Exemplo: ''la creatività'' (substantivo) vs. ''creativo'' (adjetivo).","Erro: Esquecer o artigo definido ou indefinido antes do substantivo. Exemplo: ''Prendere decisioni'' (uso correto) vs. ''Prendere decisione'' (errado)."]'::jsonb, '["A nominalização é muito comum em italiano formal, especialmente em documentos e notícias.","Alguns substantivos têm forma dupla: por exemplo, ''decidere'' pode dar ''decisione'' e ''decidimento'', mas ''decisione'' é mais comum.","Verbos que terminam em -ificare frequentemente formam substantivos com -ficazione: ''identificare'' -> ''identificazione''.","A nominalização pode ser usada em paralelo com construções infinitivas: ''Il fumare è vietato'' vs. ''Il fumo è vietato'' (mas cuidado com a mudança de significado).","Em contextos informais, os italianos às vezes preferem o infinitivo substantivado, como ''il viaggiare''.","É importante verificar o gênero do substantivo derivado: geralmente são femininos se terminam em -zione, masculinos se em -mento."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

